static bool
read_test_u32be(std::span<const std::byte> bytes, size_t off,
                uint32_t* out) noexcept
{
    if (!out || off + 4U > bytes.size()) {
        return false;
    }
    *out = (static_cast<uint32_t>(std::to_integer<uint8_t>(bytes[off + 0U]))
            << 24U)
           | (static_cast<uint32_t>(std::to_integer<uint8_t>(bytes[off + 1U]))
              << 16U)
           | (static_cast<uint32_t>(std::to_integer<uint8_t>(bytes[off + 2U]))
              << 8U)
           | (static_cast<uint32_t>(std::to_integer<uint8_t>(bytes[off + 3U]))
              << 0U);
    return true;
}

static bool
read_test_u16be(std::span<const std::byte> bytes, size_t off,
                uint16_t* out) noexcept
{
    if (!out || off + 2U > bytes.size()) {
        return false;
    }
    *out = static_cast<uint16_t>(
        (static_cast<uint16_t>(std::to_integer<uint8_t>(bytes[off + 0U])) << 8U)
        | (static_cast<uint16_t>(std::to_integer<uint8_t>(bytes[off + 1U]))
           << 0U));
    return true;
}

static bool
read_test_u_nbe(std::span<const std::byte> bytes, size_t off, size_t width,
                uint64_t* out) noexcept
{
    if (!out || width > 8U || off > bytes.size()
        || width > bytes.size() - off) {
        return false;
    }

    uint64_t value = 0U;
    for (size_t i = 0; i < width; ++i) {
        value = (value << 8U)
                | static_cast<uint64_t>(
                    std::to_integer<uint8_t>(bytes[off + i]));
    }
    *out = value;
    return true;
}

static bool
read_test_u64le(std::span<const std::byte> bytes, size_t* io_off,
                uint64_t* out) noexcept
{
    if (!io_off || !out || *io_off + 8U > bytes.size()) {
        return false;
    }
    const size_t off = *io_off;
    *out = (static_cast<uint64_t>(std::to_integer<uint8_t>(bytes[off + 0U]))
            << 0U)
           | (static_cast<uint64_t>(std::to_integer<uint8_t>(bytes[off + 1U]))
              << 8U)
           | (static_cast<uint64_t>(std::to_integer<uint8_t>(bytes[off + 2U]))
              << 16U)
           | (static_cast<uint64_t>(std::to_integer<uint8_t>(bytes[off + 3U]))
              << 24U)
           | (static_cast<uint64_t>(std::to_integer<uint8_t>(bytes[off + 4U]))
              << 32U)
           | (static_cast<uint64_t>(std::to_integer<uint8_t>(bytes[off + 5U]))
              << 40U)
           | (static_cast<uint64_t>(std::to_integer<uint8_t>(bytes[off + 6U]))
              << 48U)
           | (static_cast<uint64_t>(std::to_integer<uint8_t>(bytes[off + 7U]))
              << 56U);
    *io_off += 8U;
    return true;
}

static void
append_test_u64le(std::vector<std::byte>* out, uint64_t value) noexcept
{
    if (!out) {
        return;
    }
    out->push_back(static_cast<std::byte>(value & 0xFFU));
    out->push_back(static_cast<std::byte>((value >> 8U) & 0xFFU));
    out->push_back(static_cast<std::byte>((value >> 16U) & 0xFFU));
    out->push_back(static_cast<std::byte>((value >> 24U) & 0xFFU));
    out->push_back(static_cast<std::byte>((value >> 32U) & 0xFFU));
    out->push_back(static_cast<std::byte>((value >> 40U) & 0xFFU));
    out->push_back(static_cast<std::byte>((value >> 48U) & 0xFFU));
    out->push_back(static_cast<std::byte>((value >> 56U) & 0xFFU));
}

static std::vector<std::byte>
make_test_exr_string_attribute_payload(std::string_view name,
                                       std::string_view value)
{
    std::vector<std::byte> out;
    out.reserve(16U + name.size() + value.size());
    append_test_u64le(&out, static_cast<uint64_t>(name.size()));
    for (size_t i = 0; i < name.size(); ++i) {
        out.push_back(
            static_cast<std::byte>(static_cast<unsigned char>(name[i])));
    }
    append_test_u64le(&out, static_cast<uint64_t>(value.size()));
    for (size_t i = 0; i < value.size(); ++i) {
        out.push_back(
            static_cast<std::byte>(static_cast<unsigned char>(value[i])));
    }
    return out;
}

static bool
parse_test_exr_string_attribute_payload(std::span<const std::byte> bytes,
                                        std::string* out_name,
                                        std::string* out_value) noexcept
{
    if (!out_name || !out_value) {
        return false;
    }
    size_t off        = 0U;
    uint64_t name_len = 0U;
    if (!read_test_u64le(bytes, &off, &name_len)
        || name_len > bytes.size() - off) {
        return false;
    }
    out_name->assign(reinterpret_cast<const char*>(bytes.data() + off),
                     static_cast<size_t>(name_len));
    off += static_cast<size_t>(name_len);

    uint64_t value_len = 0U;
    if (!read_test_u64le(bytes, &off, &value_len)
        || value_len > bytes.size() - off) {
        return false;
    }
    out_value->assign(reinterpret_cast<const char*>(bytes.data() + off),
                      static_cast<size_t>(value_len));
    off += static_cast<size_t>(value_len);
    return off == bytes.size();
}

static bool
contains_byte_pair(std::span<const std::byte> bytes, uint8_t a,
                   uint8_t b) noexcept
{
    if (bytes.size() < 2U) {
        return false;
    }
    for (size_t i = 0; i + 1U < bytes.size(); ++i) {
        if (std::to_integer<uint8_t>(bytes[i + 0U]) == a
            && std::to_integer<uint8_t>(bytes[i + 1U]) == b) {
            return true;
        }
    }
    return false;
}

static void
append_fourcc(std::vector<std::byte>* out, uint32_t v)
{
    append_u32be(out, v);
}

static void
append_bytes(std::vector<std::byte>* out, std::string_view s)
{
    for (char c : s) {
        out->push_back(static_cast<std::byte>(static_cast<unsigned char>(c)));
    }
}

static void
append_bmff_box(std::vector<std::byte>* out, uint32_t type,
                std::span<const std::byte> payload)
{
    append_u32be(out, static_cast<uint32_t>(8U + payload.size()));
    append_fourcc(out, type);
    out->insert(out->end(), payload.begin(), payload.end());
}

static void
append_bmff_fullbox_header(std::vector<std::byte>* out, uint8_t version)
{
    out->push_back(std::byte { version });
    out->push_back(std::byte { 0x00 });
    out->push_back(std::byte { 0x00 });
    out->push_back(std::byte { 0x00 });
}

static void
append_test_cr3_private_media(std::vector<std::byte>* out)
{
    static constexpr std::array<std::byte, 16> kCanonUuid = {
        std::byte { 0x85 }, std::byte { 0xc0 }, std::byte { 0xb6 },
        std::byte { 0x87 }, std::byte { 0x82 }, std::byte { 0x0f },
        std::byte { 0x11 }, std::byte { 0xe0 }, std::byte { 0x81 },
        std::byte { 0x11 }, std::byte { 0xf4 }, std::byte { 0xce },
        std::byte { 0x46 }, std::byte { 0x2b }, std::byte { 0x6a },
        std::byte { 0x48 },
    };
    static constexpr std::array<std::byte, 4> kMedia = {
        std::byte { 0xa1 },
        std::byte { 0xb2 },
        std::byte { 0xc3 },
        std::byte { 0xd4 },
    };
    // CTBO's absolute offset and size cover the complete following mdat box.
    const uint64_t media_offset = out->size() + 64U;
    std::vector<std::byte> ctbo;
    append_u32be(&ctbo, 1U);
    append_u32be(&ctbo, 3U);
    append_test_u_nbe(&ctbo, 8U, media_offset);
    append_test_u_nbe(&ctbo, 8U, 8U + kMedia.size());
    std::vector<std::byte> uuid(kCanonUuid.begin(), kCanonUuid.end());
    append_bmff_box(&uuid, openmeta::fourcc('C', 'T', 'B', 'O'), ctbo);
    std::vector<std::byte> moov;
    append_bmff_box(&moov, openmeta::fourcc('u', 'u', 'i', 'd'), uuid);
    append_bmff_box(out, openmeta::fourcc('m', 'o', 'o', 'v'), moov);
    append_bmff_box(out, openmeta::fourcc('m', 'd', 'a', 't'), kMedia);
}

static std::vector<std::byte>
make_minimal_bmff_file(uint32_t major_brand,
                       std::span<const uint32_t> compatible_brands)
{
    std::vector<std::byte> ftyp_payload;
    append_fourcc(&ftyp_payload, major_brand);
    append_u32be(&ftyp_payload, 0U);
    for (size_t i = 0; i < compatible_brands.size(); ++i) {
        append_fourcc(&ftyp_payload, compatible_brands[i]);
    }

    static const std::array<std::byte, 4> kMediaData = {
        std::byte { 0x11 },
        std::byte { 0x22 },
        std::byte { 0x33 },
        std::byte { 0x44 },
    };

    std::vector<std::byte> out;
    append_bmff_box(&out, openmeta::fourcc('f', 't', 'y', 'p'),
                    std::span<const std::byte>(ftyp_payload.data(),
                                               ftyp_payload.size()));
    append_bmff_box(&out, openmeta::fourcc('m', 'd', 'a', 't'),
                    std::span<const std::byte>(kMediaData.data(),
                                               kMediaData.size()));
    return out;
}

static std::vector<std::byte>
make_minimal_heif_file()
{
    const std::array<uint32_t, 2> compat = {
        openmeta::fourcc('m', 'i', 'f', '1'),
        openmeta::fourcc('h', 'e', 'i', 'c'),
    };
    return make_minimal_bmff_file(openmeta::fourcc('h', 'e', 'i', 'c'),
                                  std::span<const uint32_t>(compat.data(),
                                                            compat.size()));
}

static std::vector<std::byte>
make_minimal_bmff_file()
{
    return make_minimal_heif_file();
}

static uint32_t
count_top_level_bmff_boxes(std::span<const std::byte> bytes,
                           uint32_t type) noexcept
{
    uint32_t count = 0U;
    size_t off     = 0U;
    while (off + 8U <= bytes.size()) {
        uint32_t box_size = 0U;
        uint32_t box_type = 0U;
        if (!read_test_u32be(bytes, off, &box_size)
            || !read_test_u32be(bytes, off + 4U, &box_type) || box_size < 8U
            || box_size > bytes.size() - off) {
            return count;
        }
        if (box_type == type) {
            count += 1U;
        }
        off += box_size;
    }
    return count;
}

static std::vector<std::byte>
make_test_bmff_exif_item_payload();

static std::vector<std::byte>
make_test_bmff_dinf(bool self_contained)
{
    std::vector<std::byte> url_payload;
    append_bmff_fullbox_header(&url_payload, 0U);
    if (self_contained) {
        url_payload[3] = std::byte { 0x01 };
    } else {
        append_bytes(&url_payload, "metadata.bin");
        url_payload.push_back(std::byte { 0x00 });
    }
    std::vector<std::byte> url_box;
    append_bmff_box(&url_box, openmeta::fourcc('u', 'r', 'l', ' '),
                    std::span<const std::byte>(url_payload.data(),
                                               url_payload.size()));

    std::vector<std::byte> dref_payload;
    append_bmff_fullbox_header(&dref_payload, 0U);
    append_u32be(&dref_payload, 1U);
    dref_payload.insert(dref_payload.end(), url_box.begin(), url_box.end());
    std::vector<std::byte> dref_box;
    append_bmff_box(&dref_box, openmeta::fourcc('d', 'r', 'e', 'f'),
                    std::span<const std::byte>(dref_payload.data(),
                                               dref_payload.size()));

    std::vector<std::byte> dinf_box;
    append_bmff_box(&dinf_box, openmeta::fourcc('d', 'i', 'n', 'f'),
                    std::span<const std::byte>(dref_box.data(),
                                               dref_box.size()));
    return dinf_box;
}

static std::vector<std::byte>
make_bmff_foreign_meta_iloc_method_target(
    uint16_t construction_method, uint16_t data_reference_index,
    bool include_idat, bool include_dref = false,
    bool dref_self_contained = false,
    uint32_t major_brand     = openmeta::fourcc('h', 'e', 'i', 'c'),
    uint8_t offset_size = 4U, uint8_t length_size = 4U)
{
    const std::array<uint32_t, 2> compatible_brands = {
        openmeta::fourcc('m', 'i', 'f', '1'),
        major_brand,
    };
    std::vector<std::byte> out = make_minimal_bmff_file(
        major_brand, std::span<const uint32_t>(compatible_brands.data(),
                                               compatible_brands.size()));

    std::vector<std::byte> pitm_payload;
    append_bmff_fullbox_header(&pitm_payload, 0U);
    append_u16be(&pitm_payload, 1U);
    std::vector<std::byte> pitm_box;
    append_bmff_box(&pitm_box, openmeta::fourcc('p', 'i', 't', 'm'),
                    std::span<const std::byte>(pitm_payload.data(),
                                               pitm_payload.size()));

    std::vector<std::byte> infe_payload;
    append_bmff_fullbox_header(&infe_payload, 2U);
    append_u16be(&infe_payload, 1U);
    append_u16be(&infe_payload, 0U);
    append_fourcc(&infe_payload, openmeta::fourcc('h', 'v', 'c', '1'));
    append_bytes(&infe_payload, "Primary");
    infe_payload.push_back(std::byte { 0x00 });
    std::vector<std::byte> infe_box;
    append_bmff_box(&infe_box, openmeta::fourcc('i', 'n', 'f', 'e'),
                    std::span<const std::byte>(infe_payload.data(),
                                               infe_payload.size()));

    std::vector<std::byte> iinf_payload;
    append_bmff_fullbox_header(&iinf_payload, 0U);
    append_u16be(&iinf_payload, 1U);
    iinf_payload.insert(iinf_payload.end(), infe_box.begin(), infe_box.end());
    std::vector<std::byte> iinf_box;
    append_bmff_box(&iinf_box, openmeta::fourcc('i', 'i', 'n', 'f'),
                    std::span<const std::byte>(iinf_payload.data(),
                                               iinf_payload.size()));

    std::vector<std::byte> iloc_payload;
    append_bmff_fullbox_header(&iloc_payload, 1U);
    iloc_payload.push_back(static_cast<std::byte>(((offset_size & 0x0FU) << 4U)
                                                  | (length_size & 0x0FU)));
    iloc_payload.push_back(std::byte { 0x40 });
    append_u16be(&iloc_payload, 1U);
    append_u16be(&iloc_payload, 1U);
    append_u16be(&iloc_payload, construction_method);
    append_u16be(&iloc_payload, data_reference_index);
    append_u32be(&iloc_payload, 0U);
    append_u16be(&iloc_payload, 1U);
    append_test_u_nbe(&iloc_payload, offset_size, 0U);
    append_test_u_nbe(&iloc_payload, length_size, 1U);
    std::vector<std::byte> iloc_box;
    append_bmff_box(&iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(iloc_payload.data(),
                                               iloc_payload.size()));

    std::vector<std::byte> idat_box;
    if (include_idat) {
        const std::array<std::byte, 1> image_payload = { std::byte { 0xAA } };
        append_bmff_box(&idat_box, openmeta::fourcc('i', 'd', 'a', 't'),
                        std::span<const std::byte>(image_payload.data(),
                                                   image_payload.size()));
    }

    std::vector<std::byte> dinf_box;
    if (include_dref) {
        dinf_box = make_test_bmff_dinf(dref_self_contained);
    }

    std::vector<std::byte> meta_payload;
    append_bmff_fullbox_header(&meta_payload, 0U);
    meta_payload.insert(meta_payload.end(), pitm_box.begin(), pitm_box.end());
    meta_payload.insert(meta_payload.end(), iinf_box.begin(), iinf_box.end());
    meta_payload.insert(meta_payload.end(), iloc_box.begin(), iloc_box.end());
    if (include_dref) {
        meta_payload.insert(meta_payload.end(), dinf_box.begin(),
                            dinf_box.end());
    }
    if (include_idat) {
        meta_payload.insert(meta_payload.end(), idat_box.begin(),
                            idat_box.end());
    }

    std::vector<std::byte> meta_box;
    append_bmff_box(&meta_box, openmeta::fourcc('m', 'e', 't', 'a'),
                    std::span<const std::byte>(meta_payload.data(),
                                               meta_payload.size()));
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    return out;
}

static std::vector<std::byte>
make_bmff_foreign_meta_merge_target()
{
    return make_bmff_foreign_meta_iloc_method_target(0x0001U, 0U, true);
}

static void
append_test_bmff_infe_v2(std::vector<std::byte>* iinf_payload, uint16_t item_id,
                         uint32_t item_type, const char* item_name)
{
    std::vector<std::byte> infe_payload;
    append_bmff_fullbox_header(&infe_payload, 2U);
    append_u16be(&infe_payload, item_id);
    append_u16be(&infe_payload, 0U);
    append_fourcc(&infe_payload, item_type);
    append_bytes(&infe_payload, item_name);
    infe_payload.push_back(std::byte { 0x00 });

    std::vector<std::byte> infe_box;
    append_bmff_box(&infe_box, openmeta::fourcc('i', 'n', 'f', 'e'),
                    std::span<const std::byte>(infe_payload.data(),
                                               infe_payload.size()));
    iinf_payload->insert(iinf_payload->end(), infe_box.begin(), infe_box.end());
}

static void
append_test_bmff_infe_v2_mime(std::vector<std::byte>* iinf_payload,
                              uint16_t item_id, const char* item_name,
                              const char* content_type)
{
    std::vector<std::byte> infe_payload;
    append_bmff_fullbox_header(&infe_payload, 2U);
    append_u16be(&infe_payload, item_id);
    append_u16be(&infe_payload, 0U);
    append_fourcc(&infe_payload, openmeta::fourcc('m', 'i', 'm', 'e'));
    append_bytes(&infe_payload, item_name);
    infe_payload.push_back(std::byte { 0x00 });
    append_bytes(&infe_payload, content_type);
    infe_payload.push_back(std::byte { 0x00 });
    infe_payload.push_back(std::byte { 0x00 });

    std::vector<std::byte> infe_box;
    append_bmff_box(&infe_box, openmeta::fourcc('i', 'n', 'f', 'e'),
                    std::span<const std::byte>(infe_payload.data(),
                                               infe_payload.size()));
    iinf_payload->insert(iinf_payload->end(), infe_box.begin(), infe_box.end());
}

static void
append_test_bmff_iref_one_to_one(std::vector<std::byte>* iref_payload,
                                 uint32_t ref_type, uint16_t from_item_id,
                                 uint16_t to_item_id)
{
    std::vector<std::byte> ref_payload;
    append_u16be(&ref_payload, from_item_id);
    append_u16be(&ref_payload, 1U);
    append_u16be(&ref_payload, to_item_id);

    std::vector<std::byte> ref_box;
    append_bmff_box(&ref_box, ref_type,
                    std::span<const std::byte>(ref_payload.data(),
                                               ref_payload.size()));
    iref_payload->insert(iref_payload->end(), ref_box.begin(), ref_box.end());
}

static std::vector<std::byte>
make_bmff_scene_policy_decode_target()
{
    std::vector<std::byte> out = make_minimal_bmff_file();

    std::vector<std::byte> pitm_payload;
    append_bmff_fullbox_header(&pitm_payload, 0U);
    append_u16be(&pitm_payload, 1U);
    std::vector<std::byte> pitm_box;
    append_bmff_box(&pitm_box, openmeta::fourcc('p', 'i', 't', 'm'),
                    std::span<const std::byte>(pitm_payload.data(),
                                               pitm_payload.size()));

    std::vector<std::byte> iinf_payload;
    append_bmff_fullbox_header(&iinf_payload, 0U);
    append_u16be(&iinf_payload, 3U);
    append_test_bmff_infe_v2(&iinf_payload, 1U,
                             openmeta::fourcc('h', 'v', 'c', '1'), "Primary");
    append_test_bmff_infe_v2(&iinf_payload, 2U,
                             openmeta::fourcc('t', 'h', 'm', 'b'), "Thumb");
    append_test_bmff_infe_v2_mime(&iinf_payload, 3U, "Manifest",
                                  "application/c2pa+jumbf");
    std::vector<std::byte> iinf_box;
    append_bmff_box(&iinf_box, openmeta::fourcc('i', 'i', 'n', 'f'),
                    std::span<const std::byte>(iinf_payload.data(),
                                               iinf_payload.size()));

    std::vector<std::byte> iref_payload;
    append_bmff_fullbox_header(&iref_payload, 0U);
    append_test_bmff_iref_one_to_one(&iref_payload,
                                     openmeta::fourcc('t', 'h', 'm', 'b'), 1U,
                                     2U);
    append_test_bmff_iref_one_to_one(&iref_payload,
                                     openmeta::fourcc('c', 'd', 's', 'c'), 1U,
                                     3U);
    std::vector<std::byte> iref_box;
    append_bmff_box(&iref_box, openmeta::fourcc('i', 'r', 'e', 'f'),
                    std::span<const std::byte>(iref_payload.data(),
                                               iref_payload.size()));

    std::vector<std::byte> meta_payload;
    append_bmff_fullbox_header(&meta_payload, 0U);
    meta_payload.insert(meta_payload.end(), pitm_box.begin(), pitm_box.end());
    meta_payload.insert(meta_payload.end(), iinf_box.begin(), iinf_box.end());
    meta_payload.insert(meta_payload.end(), iref_box.begin(), iref_box.end());

    std::vector<std::byte> meta_box;
    append_bmff_box(&meta_box, openmeta::fourcc('m', 'e', 't', 'a'),
                    std::span<const std::byte>(meta_payload.data(),
                                               meta_payload.size()));
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    return out;
}

static std::vector<std::byte>
make_bmff_foreign_meta_iloc_method2_reference_target(
    bool include_iref, bool referenced_item_is_exif, bool use_extent_indices,
    uint16_t referenced_item_data_reference_index = 0U,
    uint16_t second_target_data_reference_index   = 0U,
    uint16_t first_target_construction_method = 1U, bool include_dref = false,
    bool dref_self_contained = true,
    uint32_t major_brand     = openmeta::fourcc('h', 'e', 'i', 'c'),
    uint64_t* out_first_target_extent_offset = nullptr)
{
    const std::array<uint32_t, 2> compatible_brands = {
        openmeta::fourcc('m', 'i', 'f', '1'),
        major_brand,
    };
    std::vector<std::byte> out = make_minimal_bmff_file(
        major_brand, std::span<const uint32_t>(compatible_brands.data(),
                                               compatible_brands.size()));

    uint64_t first_target_extent_offset = 0U;
    if (first_target_construction_method == 0U) {
        static constexpr std::array<std::byte, 6> kMethod0Data = {
            std::byte { 'A' }, std::byte { 'B' }, std::byte { 'C' },
            std::byte { 'D' }, std::byte { 'E' }, std::byte { 'F' },
        };
        first_target_extent_offset = static_cast<uint64_t>(out.size()) + 8U;
        append_bmff_box(&out, openmeta::fourcc('m', 'd', 'a', 't'),
                        std::span<const std::byte>(kMethod0Data.data(),
                                                   kMethod0Data.size()));
    }
    if (out_first_target_extent_offset) {
        *out_first_target_extent_offset = first_target_extent_offset;
    }

    std::vector<std::byte> idat_payload;
    uint32_t first_ref_length  = 0U;
    uint32_t second_ref_offset = 0U;
    uint32_t second_ref_length = 0U;
    if (referenced_item_is_exif) {
        const std::vector<std::byte> old_exif
            = make_test_bmff_exif_item_payload();
        first_ref_length = static_cast<uint32_t>(old_exif.size());
        idat_payload.insert(idat_payload.end(), old_exif.begin(),
                            old_exif.end());
    } else {
        idat_payload      = { std::byte { 'A' }, std::byte { 'B' },
                              std::byte { 'C' }, std::byte { 'D' },
                              std::byte { 'E' }, std::byte { 'F' } };
        first_ref_length  = 3U;
        second_ref_offset = 3U;
        second_ref_length = 3U;
    }

    std::vector<std::byte> pitm_payload;
    append_bmff_fullbox_header(&pitm_payload, 0U);
    append_u16be(&pitm_payload, 1U);
    std::vector<std::byte> pitm_box;
    append_bmff_box(&pitm_box, openmeta::fourcc('p', 'i', 't', 'm'),
                    std::span<const std::byte>(pitm_payload.data(),
                                               pitm_payload.size()));

    const uint32_t item_count = referenced_item_is_exif ? 2U : 3U;
    std::vector<std::byte> iinf_payload;
    append_bmff_fullbox_header(&iinf_payload, 0U);
    append_u16be(&iinf_payload, static_cast<uint16_t>(item_count));
    append_test_bmff_infe_v2(&iinf_payload, 1U,
                             openmeta::fourcc('h', 'v', 'c', '1'), "Primary");
    append_test_bmff_infe_v2(&iinf_payload, 2U,
                             referenced_item_is_exif
                                 ? openmeta::fourcc('E', 'x', 'i', 'f')
                                 : openmeta::fourcc('h', 'v', 'c', '1'),
                             referenced_item_is_exif ? "Exif" : "TileA");
    if (!referenced_item_is_exif) {
        append_test_bmff_infe_v2(&iinf_payload, 3U,
                                 openmeta::fourcc('h', 'v', 'c', '1'), "TileB");
    }
    std::vector<std::byte> iinf_box;
    append_bmff_box(&iinf_box, openmeta::fourcc('i', 'i', 'n', 'f'),
                    std::span<const std::byte>(iinf_payload.data(),
                                               iinf_payload.size()));

    std::vector<std::byte> iloc_payload;
    append_bmff_fullbox_header(&iloc_payload, 2U);
    iloc_payload.push_back(std::byte { 0x44 });
    iloc_payload.push_back(use_extent_indices ? std::byte { 0x02 }
                                              : std::byte { 0x00 });
    append_u32be(&iloc_payload, item_count);

    append_u32be(&iloc_payload, 2U);
    append_u16be(&iloc_payload, first_target_construction_method);
    append_u16be(&iloc_payload, referenced_item_data_reference_index);
    append_u16be(&iloc_payload, 1U);
    if (use_extent_indices) {
        append_u16be(&iloc_payload,
                     first_target_construction_method == 2U ? 1U : 0U);
    }
    append_u32be(&iloc_payload,
                 static_cast<uint32_t>(first_target_extent_offset));
    append_u32be(&iloc_payload, first_ref_length);

    if (!referenced_item_is_exif) {
        append_u32be(&iloc_payload, 3U);
        append_u16be(&iloc_payload, 0x0001U);
        append_u16be(&iloc_payload, second_target_data_reference_index);
        append_u16be(&iloc_payload, 1U);
        if (use_extent_indices) {
            append_u16be(&iloc_payload, 0U);
        }
        append_u32be(&iloc_payload, second_ref_offset);
        append_u32be(&iloc_payload, second_ref_length);
    }

    append_u32be(&iloc_payload, 1U);
    append_u16be(&iloc_payload, 0x0002U);
    append_u16be(&iloc_payload, 0U);
    append_u16be(&iloc_payload,
                 static_cast<uint16_t>(referenced_item_is_exif ? 1U : 2U));
    if (use_extent_indices) {
        append_u16be(&iloc_payload, 1U);
    }
    append_u32be(&iloc_payload, 0U);
    append_u32be(&iloc_payload, first_ref_length);
    if (!referenced_item_is_exif) {
        if (use_extent_indices) {
            append_u16be(&iloc_payload, 2U);
        }
        append_u32be(&iloc_payload, 0U);
        append_u32be(&iloc_payload, second_ref_length);
    }
    std::vector<std::byte> iloc_box;
    append_bmff_box(&iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(iloc_payload.data(),
                                               iloc_payload.size()));

    std::vector<std::byte> iref_box;
    if (include_iref) {
        std::vector<std::byte> iref_iloc_payload;
        append_u32be(&iref_iloc_payload, 1U);
        append_u16be(&iref_iloc_payload,
                     static_cast<uint16_t>(referenced_item_is_exif ? 1U : 2U));
        append_u32be(&iref_iloc_payload, 2U);
        if (!referenced_item_is_exif) {
            append_u32be(&iref_iloc_payload, 3U);
        }
        std::vector<std::byte> iref_iloc_box;
        append_bmff_box(&iref_iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                        std::span<const std::byte>(iref_iloc_payload.data(),
                                                   iref_iloc_payload.size()));

        std::vector<std::byte> iref_payload;
        append_bmff_fullbox_header(&iref_payload, 1U);
        iref_payload.insert(iref_payload.end(), iref_iloc_box.begin(),
                            iref_iloc_box.end());
        if (!referenced_item_is_exif
            && first_target_construction_method == 2U) {
            std::vector<std::byte> nested_iref_iloc_payload;
            append_u32be(&nested_iref_iloc_payload, 2U);
            append_u16be(&nested_iref_iloc_payload, 1U);
            append_u32be(&nested_iref_iloc_payload, 3U);
            std::vector<std::byte> nested_iref_iloc_box;
            append_bmff_box(
                &nested_iref_iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                std::span<const std::byte>(nested_iref_iloc_payload.data(),
                                           nested_iref_iloc_payload.size()));
            iref_payload.insert(iref_payload.end(),
                                nested_iref_iloc_box.begin(),
                                nested_iref_iloc_box.end());
        }
        append_bmff_box(&iref_box, openmeta::fourcc('i', 'r', 'e', 'f'),
                        std::span<const std::byte>(iref_payload.data(),
                                                   iref_payload.size()));
    }

    std::vector<std::byte> idat_box;
    append_bmff_box(&idat_box, openmeta::fourcc('i', 'd', 'a', 't'),
                    std::span<const std::byte>(idat_payload.data(),
                                               idat_payload.size()));

    const std::vector<std::byte> dinf_box
        = include_dref ? make_test_bmff_dinf(dref_self_contained)
                       : std::vector<std::byte> {};

    std::vector<std::byte> meta_payload;
    append_bmff_fullbox_header(&meta_payload, 0U);
    meta_payload.insert(meta_payload.end(), pitm_box.begin(), pitm_box.end());
    meta_payload.insert(meta_payload.end(), iinf_box.begin(), iinf_box.end());
    meta_payload.insert(meta_payload.end(), iloc_box.begin(), iloc_box.end());
    if (include_iref) {
        meta_payload.insert(meta_payload.end(), iref_box.begin(),
                            iref_box.end());
    }
    meta_payload.insert(meta_payload.end(), dinf_box.begin(), dinf_box.end());
    meta_payload.insert(meta_payload.end(), idat_box.begin(), idat_box.end());

    std::vector<std::byte> meta_box;
    append_bmff_box(&meta_box, openmeta::fourcc('m', 'e', 't', 'a'),
                    std::span<const std::byte>(meta_payload.data(),
                                               meta_payload.size()));
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    return out;
}

struct TestBmffNestedMethod2FixtureOptions final {
    bool use_extent_indices                = true;
    bool mdat_after_meta                   = false;
    bool include_dref                      = false;
    bool dref_self_contained               = true;
    bool terminal_is_exif                  = false;
    bool primary_direct_terminal_reference = false;
    bool omit_nested_reference             = false;
    bool third_level_chain                 = false;
    uint16_t nested_method                 = 2U;
    uint16_t terminal_method               = 1U;
    uint16_t outer_method                  = 2U;
    uint16_t repeated_nested_targets       = 1U;
    uint16_t nested_extent_count           = 1U;
    uint16_t outer_data_reference_index    = 0U;
    uint16_t nested_data_reference_index   = 0U;
    uint16_t terminal_data_reference_index = 0U;
    uint32_t nested_reference_target       = 3U;
    uint8_t offset_width                   = 4U;
    uint8_t length_width                   = 4U;
    uint8_t base_width                     = 0U;
    uint64_t outer_base_offset             = 0U;
    uint64_t outer_extent_offset           = 0U;
    uint64_t outer_extent_length           = 3U;
    uint64_t nested_base_offset            = 0U;
    uint64_t nested_extent_offset          = 0U;
    uint64_t nested_extent_length          = 3U;
    uint64_t terminal_base_offset          = 0U;
    uint64_t terminal_extent_offset        = 0U;
    uint64_t terminal_extent_length        = 3U;
    uint64_t direct_terminal_extent_offset = 0U;
    uint64_t direct_terminal_extent_length = 2U;
};

static std::vector<std::byte>
make_bmff_foreign_meta_nested_method2_target(
    const TestBmffNestedMethod2FixtureOptions& options)
{
    if (options.offset_width > 8U || options.length_width > 8U
        || options.base_width > 8U || options.nested_extent_count == 0U
        || options.repeated_nested_targets == 0U
        || (options.primary_direct_terminal_reference
            && options.repeated_nested_targets
                   == std::numeric_limits<uint16_t>::max())) {
        return {};
    }

    const uint16_t outer_extent_count = static_cast<uint16_t>(
        options.repeated_nested_targets
        + (options.primary_direct_terminal_reference ? 1U : 0U));
    const bool has_mdat = options.nested_method == 0U
                          || options.terminal_method == 0U;
    std::vector<std::byte> out   = make_minimal_bmff_file();
    uint64_t mdat_payload_offset = 0U;
    static constexpr std::array<std::byte, 6U> kMdatBytes = {
        std::byte { 'A' }, std::byte { 'B' }, std::byte { 'C' },
        std::byte { 'D' }, std::byte { 'E' }, std::byte { 'F' },
    };
    std::vector<std::byte> mdat_box;
    if (has_mdat) {
        append_bmff_box(&mdat_box, openmeta::fourcc('m', 'd', 'a', 't'),
                        std::span<const std::byte>(kMdatBytes.data(),
                                                   kMdatBytes.size()));
        if (!options.mdat_after_meta) {
            mdat_payload_offset = static_cast<uint64_t>(out.size()) + 8U;
            out.insert(out.end(), mdat_box.begin(), mdat_box.end());
        }
    }

    std::vector<std::byte> idat_payload;
    uint64_t terminal_extent_length = options.terminal_extent_length;
    if (options.terminal_is_exif) {
        idat_payload = make_test_bmff_exif_item_payload();
        if (terminal_extent_length == 0U) {
            terminal_extent_length = static_cast<uint64_t>(idat_payload.size());
        }
    } else {
        idat_payload.assign(kMdatBytes.begin(), kMdatBytes.end());
    }

    std::vector<std::byte> pitm_payload;
    append_bmff_fullbox_header(&pitm_payload, 0U);
    append_u16be(&pitm_payload, 1U);
    std::vector<std::byte> pitm_box;
    append_bmff_box(&pitm_box, openmeta::fourcc('p', 'i', 't', 'm'),
                    std::span<const std::byte>(pitm_payload.data(),
                                               pitm_payload.size()));

    std::vector<std::byte> iinf_payload;
    append_bmff_fullbox_header(&iinf_payload, 0U);
    append_u16be(&iinf_payload, options.third_level_chain ? 4U : 3U);
    append_test_bmff_infe_v2(&iinf_payload, 1U,
                             openmeta::fourcc('h', 'v', 'c', '1'), "Primary");
    append_test_bmff_infe_v2(&iinf_payload, 2U,
                             openmeta::fourcc('h', 'v', 'c', '1'), "Nested");
    if (options.third_level_chain) {
        append_test_bmff_infe_v2(&iinf_payload, 3U,
                                 openmeta::fourcc('h', 'v', 'c', '1'),
                                 "Intermediate");
        append_test_bmff_infe_v2(&iinf_payload, 4U,
                                 options.terminal_is_exif
                                     ? openmeta::fourcc('E', 'x', 'i', 'f')
                                     : openmeta::fourcc('h', 'v', 'c', '1'),
                                 options.terminal_is_exif ? "Exif"
                                                          : "Terminal");
    } else {
        append_test_bmff_infe_v2(&iinf_payload, 3U,
                                 options.terminal_is_exif
                                     ? openmeta::fourcc('E', 'x', 'i', 'f')
                                     : openmeta::fourcc('h', 'v', 'c', '1'),
                                 options.terminal_is_exif ? "Exif"
                                                          : "Terminal");
    }
    std::vector<std::byte> iinf_box;
    append_bmff_box(&iinf_box, openmeta::fourcc('i', 'i', 'n', 'f'),
                    std::span<const std::byte>(iinf_payload.data(),
                                               iinf_payload.size()));

    const size_t index_width = options.use_extent_indices ? 2U : 0U;
    const uint64_t nested_input_extent_offset
        = options.nested_method == 0U && has_mdat && !options.mdat_after_meta
              ? mdat_payload_offset + options.nested_extent_offset
              : options.nested_extent_offset;
    const uint64_t terminal_input_extent_offset
        = options.terminal_method == 0U && has_mdat && !options.mdat_after_meta
              ? mdat_payload_offset + options.terminal_extent_offset
              : options.terminal_extent_offset;
    std::vector<std::byte> iloc_payload;
    append_bmff_fullbox_header(&iloc_payload, 2U);
    iloc_payload.push_back(static_cast<std::byte>((options.offset_width << 4U)
                                                  | options.length_width));
    iloc_payload.push_back(
        static_cast<std::byte>((options.base_width << 4U) | index_width));
    append_u32be(&iloc_payload, options.third_level_chain ? 4U : 3U);

    append_u32be(&iloc_payload, 2U);
    append_u16be(&iloc_payload, options.nested_method);
    append_u16be(&iloc_payload, options.nested_data_reference_index);
    append_test_u_nbe(&iloc_payload, options.base_width,
                      options.nested_base_offset);
    append_u16be(&iloc_payload, options.nested_extent_count);
    size_t nested_extent_offset_field = 0U;
    for (uint32_t i = 0U; i < options.nested_extent_count; ++i) {
        if (options.use_extent_indices) {
            append_u16be(&iloc_payload, static_cast<uint16_t>(i + 1U));
        }
        if (i == 0U) {
            nested_extent_offset_field = iloc_payload.size();
        }
        append_test_u_nbe(&iloc_payload, options.offset_width,
                          nested_input_extent_offset);
        append_test_u_nbe(&iloc_payload, options.length_width,
                          options.nested_extent_length);
    }

    if (options.third_level_chain) {
        append_u32be(&iloc_payload, 3U);
        append_u16be(&iloc_payload, 2U);
        append_u16be(&iloc_payload, options.nested_data_reference_index);
        append_test_u_nbe(&iloc_payload, options.base_width, 0U);
        append_u16be(&iloc_payload, 1U);
        if (options.use_extent_indices) {
            append_u16be(&iloc_payload, 1U);
        }
        append_test_u_nbe(&iloc_payload, options.offset_width, 0U);
        append_test_u_nbe(&iloc_payload, options.length_width,
                          terminal_extent_length);
    }

    const uint32_t terminal_item_id = options.third_level_chain ? 4U : 3U;
    append_u32be(&iloc_payload, terminal_item_id);
    append_u16be(&iloc_payload, options.terminal_method);
    append_u16be(&iloc_payload, options.terminal_data_reference_index);
    append_test_u_nbe(&iloc_payload, options.base_width,
                      options.terminal_base_offset);
    append_u16be(&iloc_payload, 1U);
    if (options.use_extent_indices) {
        append_u16be(&iloc_payload, 0U);
    }
    const size_t terminal_extent_offset_field = iloc_payload.size();
    append_test_u_nbe(&iloc_payload, options.offset_width,
                      terminal_input_extent_offset);
    append_test_u_nbe(&iloc_payload, options.length_width,
                      terminal_extent_length);

    append_u32be(&iloc_payload, 1U);
    append_u16be(&iloc_payload, options.outer_method);
    append_u16be(&iloc_payload, options.outer_data_reference_index);
    append_test_u_nbe(&iloc_payload, options.base_width,
                      options.outer_base_offset);
    append_u16be(&iloc_payload, outer_extent_count);
    for (uint32_t i = 0U; i < options.repeated_nested_targets; ++i) {
        if (options.use_extent_indices) {
            append_u16be(&iloc_payload, options.outer_method == 2U
                                            ? static_cast<uint16_t>(i + 1U)
                                            : 0U);
        }
        append_test_u_nbe(&iloc_payload, options.offset_width,
                          options.outer_extent_offset);
        append_test_u_nbe(&iloc_payload, options.length_width,
                          options.outer_extent_length);
    }
    if (options.primary_direct_terminal_reference) {
        if (options.use_extent_indices) {
            append_u16be(&iloc_payload,
                         options.outer_method == 2U
                             ? static_cast<uint16_t>(
                                   options.repeated_nested_targets + 1U)
                             : 0U);
        }
        append_test_u_nbe(&iloc_payload, options.offset_width,
                          options.direct_terminal_extent_offset);
        append_test_u_nbe(&iloc_payload, options.length_width,
                          options.direct_terminal_extent_length);
    }
    std::vector<std::byte> iloc_box;
    append_bmff_box(&iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(iloc_payload.data(),
                                               iloc_payload.size()));

    std::vector<std::byte> iref_payload;
    append_bmff_fullbox_header(&iref_payload, 1U);
    std::vector<std::byte> outer_refs_payload;
    append_u32be(&outer_refs_payload, 1U);
    append_u16be(&outer_refs_payload, outer_extent_count);
    for (uint32_t i = 0U; i < options.repeated_nested_targets; ++i) {
        append_u32be(&outer_refs_payload, 2U);
    }
    if (options.primary_direct_terminal_reference) {
        append_u32be(&outer_refs_payload, terminal_item_id);
    }
    std::vector<std::byte> outer_refs_box;
    append_bmff_box(&outer_refs_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(outer_refs_payload.data(),
                                               outer_refs_payload.size()));
    iref_payload.insert(iref_payload.end(), outer_refs_box.begin(),
                        outer_refs_box.end());

    std::vector<std::byte> nested_refs_payload;
    append_u32be(&nested_refs_payload, 2U);
    append_u16be(&nested_refs_payload, options.nested_extent_count);
    for (uint32_t i = 0U; i < options.nested_extent_count; ++i) {
        append_u32be(&nested_refs_payload, options.nested_reference_target);
    }
    std::vector<std::byte> nested_refs_box;
    append_bmff_box(&nested_refs_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(nested_refs_payload.data(),
                                               nested_refs_payload.size()));
    if (!options.omit_nested_reference) {
        iref_payload.insert(iref_payload.end(), nested_refs_box.begin(),
                            nested_refs_box.end());
    }
    if (options.third_level_chain) {
        std::vector<std::byte> intermediate_refs_payload;
        append_u32be(&intermediate_refs_payload, 3U);
        append_u16be(&intermediate_refs_payload, 1U);
        append_u32be(&intermediate_refs_payload, 4U);
        std::vector<std::byte> intermediate_refs_box;
        append_bmff_box(
            &intermediate_refs_box, openmeta::fourcc('i', 'l', 'o', 'c'),
            std::span<const std::byte>(intermediate_refs_payload.data(),
                                       intermediate_refs_payload.size()));
        iref_payload.insert(iref_payload.end(), intermediate_refs_box.begin(),
                            intermediate_refs_box.end());
    }
    std::vector<std::byte> iref_box;
    append_bmff_box(&iref_box, openmeta::fourcc('i', 'r', 'e', 'f'),
                    std::span<const std::byte>(iref_payload.data(),
                                               iref_payload.size()));

    std::vector<std::byte> idat_box;
    append_bmff_box(&idat_box, openmeta::fourcc('i', 'd', 'a', 't'),
                    std::span<const std::byte>(idat_payload.data(),
                                               idat_payload.size()));
    const std::vector<std::byte> dinf_box
        = options.include_dref
              ? make_test_bmff_dinf(options.dref_self_contained)
              : std::vector<std::byte> {};

    std::vector<std::byte> meta_payload;
    append_bmff_fullbox_header(&meta_payload, 0U);
    meta_payload.insert(meta_payload.end(), pitm_box.begin(), pitm_box.end());
    meta_payload.insert(meta_payload.end(), iinf_box.begin(), iinf_box.end());
    const size_t iloc_child_offset = meta_payload.size();
    meta_payload.insert(meta_payload.end(), iloc_box.begin(), iloc_box.end());
    meta_payload.insert(meta_payload.end(), iref_box.begin(), iref_box.end());
    meta_payload.insert(meta_payload.end(), dinf_box.begin(), dinf_box.end());
    meta_payload.insert(meta_payload.end(), idat_box.begin(), idat_box.end());
    std::vector<std::byte> meta_box;
    append_bmff_box(&meta_box, openmeta::fourcc('m', 'e', 't', 'a'),
                    std::span<const std::byte>(meta_payload.data(),
                                               meta_payload.size()));

    const size_t meta_offset = out.size();
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    if (has_mdat && options.mdat_after_meta) {
        mdat_payload_offset = static_cast<uint64_t>(out.size()) + 8U;
        out.insert(out.end(), mdat_box.begin(), mdat_box.end());
        const size_t iloc_payload_offset = meta_offset + 8U + iloc_child_offset
                                           + 8U;
        if (options.nested_method == 0U
            && !write_test_u_nbe(
                &out, iloc_payload_offset + nested_extent_offset_field,
                options.offset_width,
                mdat_payload_offset + options.nested_extent_offset)) {
            return {};
        }
        if (options.terminal_method == 0U
            && !write_test_u_nbe(
                &out, iloc_payload_offset + terminal_extent_offset_field,
                options.offset_width,
                mdat_payload_offset + options.terminal_extent_offset)) {
            return {};
        }
    }
    return out;
}

static std::vector<std::byte>
make_bmff_foreign_meta_existing_exif_xmp_target(bool include_graph_extensions
                                                = false,
                                                uint8_t grpl_version = 0U)
{
    std::vector<std::byte> out = make_minimal_bmff_file();

    const std::vector<std::byte> old_exif = make_test_bmff_exif_item_payload();
    const std::vector<std::byte> old_xmp  = {
        std::byte { '<' }, std::byte { 'o' }, std::byte { 'l' },
        std::byte { 'd' }, std::byte { '-' }, std::byte { 'x' },
        std::byte { 'm' }, std::byte { 'p' }, std::byte { '/' },
        std::byte { '>' },
    };

    std::vector<std::byte> idat_payload;
    idat_payload.push_back(std::byte { 0xAA });
    const uint32_t exif_offset = static_cast<uint32_t>(idat_payload.size());
    idat_payload.insert(idat_payload.end(), old_exif.begin(), old_exif.end());
    const uint32_t xmp_offset = static_cast<uint32_t>(idat_payload.size());
    idat_payload.insert(idat_payload.end(), old_xmp.begin(), old_xmp.end());

    std::vector<std::byte> pitm_payload;
    append_bmff_fullbox_header(&pitm_payload, 0U);
    append_u16be(&pitm_payload, 1U);
    std::vector<std::byte> pitm_box;
    append_bmff_box(&pitm_box, openmeta::fourcc('p', 'i', 't', 'm'),
                    std::span<const std::byte>(pitm_payload.data(),
                                               pitm_payload.size()));

    std::vector<std::byte> primary_infe_payload;
    append_bmff_fullbox_header(&primary_infe_payload, 2U);
    append_u16be(&primary_infe_payload, 1U);
    append_u16be(&primary_infe_payload, 0U);
    append_fourcc(&primary_infe_payload, openmeta::fourcc('h', 'v', 'c', '1'));
    append_bytes(&primary_infe_payload, "Primary");
    primary_infe_payload.push_back(std::byte { 0x00 });
    std::vector<std::byte> primary_infe_box;
    append_bmff_box(&primary_infe_box, openmeta::fourcc('i', 'n', 'f', 'e'),
                    std::span<const std::byte>(primary_infe_payload.data(),
                                               primary_infe_payload.size()));

    std::vector<std::byte> exif_infe_payload;
    append_bmff_fullbox_header(&exif_infe_payload, 2U);
    append_u16be(&exif_infe_payload, 2U);
    append_u16be(&exif_infe_payload, 0U);
    append_fourcc(&exif_infe_payload, openmeta::fourcc('E', 'x', 'i', 'f'));
    append_bytes(&exif_infe_payload, "Exif");
    exif_infe_payload.push_back(std::byte { 0x00 });
    std::vector<std::byte> exif_infe_box;
    append_bmff_box(&exif_infe_box, openmeta::fourcc('i', 'n', 'f', 'e'),
                    std::span<const std::byte>(exif_infe_payload.data(),
                                               exif_infe_payload.size()));

    std::vector<std::byte> xmp_infe_payload;
    append_bmff_fullbox_header(&xmp_infe_payload, 2U);
    append_u16be(&xmp_infe_payload, 3U);
    append_u16be(&xmp_infe_payload, 0U);
    append_fourcc(&xmp_infe_payload, openmeta::fourcc('m', 'i', 'm', 'e'));
    append_bytes(&xmp_infe_payload, "XMP");
    xmp_infe_payload.push_back(std::byte { 0x00 });
    append_bytes(&xmp_infe_payload, "application/rdf+xml");
    xmp_infe_payload.push_back(std::byte { 0x00 });
    xmp_infe_payload.push_back(std::byte { 0x00 });
    std::vector<std::byte> xmp_infe_box;
    append_bmff_box(&xmp_infe_box, openmeta::fourcc('i', 'n', 'f', 'e'),
                    std::span<const std::byte>(xmp_infe_payload.data(),
                                               xmp_infe_payload.size()));

    std::vector<std::byte> iinf_payload;
    append_bmff_fullbox_header(&iinf_payload, 0U);
    append_u16be(&iinf_payload, 3U);
    iinf_payload.insert(iinf_payload.end(), primary_infe_box.begin(),
                        primary_infe_box.end());
    iinf_payload.insert(iinf_payload.end(), exif_infe_box.begin(),
                        exif_infe_box.end());
    iinf_payload.insert(iinf_payload.end(), xmp_infe_box.begin(),
                        xmp_infe_box.end());
    std::vector<std::byte> iinf_box;
    append_bmff_box(&iinf_box, openmeta::fourcc('i', 'i', 'n', 'f'),
                    std::span<const std::byte>(iinf_payload.data(),
                                               iinf_payload.size()));

    std::vector<std::byte> iloc_payload;
    append_bmff_fullbox_header(&iloc_payload, 1U);
    iloc_payload.push_back(std::byte { 0x44 });
    iloc_payload.push_back(std::byte { 0x40 });
    append_u16be(&iloc_payload, 3U);
    const uint16_t item_ids[] = { 1U, 2U, 3U };
    const uint32_t offsets[]  = { 0U, exif_offset, xmp_offset };
    const uint32_t lengths[]  = {
        1U,
        static_cast<uint32_t>(old_exif.size()),
        static_cast<uint32_t>(old_xmp.size()),
    };
    for (size_t i = 0; i < 3U; ++i) {
        append_u16be(&iloc_payload, item_ids[i]);
        append_u16be(&iloc_payload, 0x0001U);
        append_u16be(&iloc_payload, 0U);
        append_u32be(&iloc_payload, 0U);
        append_u16be(&iloc_payload, 1U);
        append_u32be(&iloc_payload, offsets[i]);
        append_u32be(&iloc_payload, lengths[i]);
    }
    std::vector<std::byte> iloc_box;
    append_bmff_box(&iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(iloc_payload.data(),
                                               iloc_payload.size()));

    std::vector<std::byte> cdsc_payload;
    append_u16be(&cdsc_payload, 2U);
    append_u16be(&cdsc_payload, 1U);
    append_u16be(&cdsc_payload, 1U);
    append_u16be(&cdsc_payload, 3U);
    append_u16be(&cdsc_payload, 1U);
    append_u16be(&cdsc_payload, 1U);
    std::vector<std::byte> cdsc_box;
    append_bmff_box(&cdsc_box, openmeta::fourcc('c', 'd', 's', 'c'),
                    std::span<const std::byte>(cdsc_payload.data(),
                                               cdsc_payload.size()));
    std::vector<std::byte> iref_payload;
    append_bmff_fullbox_header(&iref_payload, 0U);
    iref_payload.insert(iref_payload.end(), cdsc_box.begin(), cdsc_box.end());
    if (include_graph_extensions) {
        std::vector<std::byte> auxl_payload;
        append_u16be(&auxl_payload, 1U);
        append_u16be(&auxl_payload, 1U);
        append_u16be(&auxl_payload, 3U);
        std::vector<std::byte> auxl_box;
        append_bmff_box(&auxl_box, openmeta::fourcc('a', 'u', 'x', 'l'),
                        std::span<const std::byte>(auxl_payload.data(),
                                                   auxl_payload.size()));
        iref_payload.insert(iref_payload.end(), auxl_box.begin(),
                            auxl_box.end());
    }
    std::vector<std::byte> iref_box;
    append_bmff_box(&iref_box, openmeta::fourcc('i', 'r', 'e', 'f'),
                    std::span<const std::byte>(iref_payload.data(),
                                               iref_payload.size()));

    std::vector<std::byte> idat_box;
    append_bmff_box(&idat_box, openmeta::fourcc('i', 'd', 'a', 't'),
                    std::span<const std::byte>(idat_payload.data(),
                                               idat_payload.size()));

    std::vector<std::byte> grpl_box;
    std::vector<std::byte> iprp_box;
    if (include_graph_extensions) {
        std::vector<std::byte> group_payload;
        append_bmff_fullbox_header(&group_payload, grpl_version);
        append_u32be(&group_payload, 10U);
        append_u32be(&group_payload, 2U);
        append_u32be(&group_payload, 1U);
        append_u32be(&group_payload, 3U);
        std::vector<std::byte> group_box;
        append_bmff_box(&group_box, openmeta::fourcc('a', 'l', 't', 'r'),
                        std::span<const std::byte>(group_payload.data(),
                                                   group_payload.size()));
        append_bmff_box(&grpl_box, openmeta::fourcc('g', 'r', 'p', 'l'),
                        std::span<const std::byte>(group_box.data(),
                                                   group_box.size()));

        std::vector<std::byte> ispe_payload;
        append_bmff_fullbox_header(&ispe_payload, 0U);
        append_u32be(&ispe_payload, 64U);
        append_u32be(&ispe_payload, 32U);
        std::vector<std::byte> ispe_box;
        append_bmff_box(&ispe_box, openmeta::fourcc('i', 's', 'p', 'e'),
                        std::span<const std::byte>(ispe_payload.data(),
                                                   ispe_payload.size()));
        std::vector<std::byte> ipco_box;
        append_bmff_box(&ipco_box, openmeta::fourcc('i', 'p', 'c', 'o'),
                        std::span<const std::byte>(ispe_box.data(),
                                                   ispe_box.size()));

        std::vector<std::byte> ipma_payload;
        append_bmff_fullbox_header(&ipma_payload, 0U);
        append_u32be(&ipma_payload, 1U);
        append_u16be(&ipma_payload, 3U);
        ipma_payload.push_back(std::byte { 0x01 });
        ipma_payload.push_back(std::byte { 0x01 });
        std::vector<std::byte> ipma_box;
        append_bmff_box(&ipma_box, openmeta::fourcc('i', 'p', 'm', 'a'),
                        std::span<const std::byte>(ipma_payload.data(),
                                                   ipma_payload.size()));

        std::vector<std::byte> iprp_payload;
        iprp_payload.insert(iprp_payload.end(), ipco_box.begin(),
                            ipco_box.end());
        iprp_payload.insert(iprp_payload.end(), ipma_box.begin(),
                            ipma_box.end());
        append_bmff_box(&iprp_box, openmeta::fourcc('i', 'p', 'r', 'p'),
                        std::span<const std::byte>(iprp_payload.data(),
                                                   iprp_payload.size()));
    }

    std::vector<std::byte> meta_payload;
    append_bmff_fullbox_header(&meta_payload, 0U);
    meta_payload.insert(meta_payload.end(), pitm_box.begin(), pitm_box.end());
    meta_payload.insert(meta_payload.end(), iinf_box.begin(), iinf_box.end());
    meta_payload.insert(meta_payload.end(), iloc_box.begin(), iloc_box.end());
    meta_payload.insert(meta_payload.end(), iref_box.begin(), iref_box.end());
    if (include_graph_extensions) {
        meta_payload.insert(meta_payload.end(), grpl_box.begin(),
                            grpl_box.end());
        meta_payload.insert(meta_payload.end(), iprp_box.begin(),
                            iprp_box.end());
    }
    meta_payload.insert(meta_payload.end(), idat_box.begin(), idat_box.end());

    std::vector<std::byte> meta_box;
    append_bmff_box(&meta_box, openmeta::fourcc('m', 'e', 't', 'a'),
                    std::span<const std::byte>(meta_payload.data(),
                                               meta_payload.size()));
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    return out;
}

static std::vector<std::byte>
make_bmff_foreign_meta_iloc_v2_high_item_id_target()
{
    std::vector<std::byte> out               = make_minimal_bmff_file();
    static constexpr uint32_t kPrimaryItemId = 70000U;

    std::vector<std::byte> pitm_payload;
    append_bmff_fullbox_header(&pitm_payload, 1U);
    append_u32be(&pitm_payload, kPrimaryItemId);
    std::vector<std::byte> pitm_box;
    append_bmff_box(&pitm_box, openmeta::fourcc('p', 'i', 't', 'm'),
                    std::span<const std::byte>(pitm_payload.data(),
                                               pitm_payload.size()));

    std::vector<std::byte> infe_payload;
    append_bmff_fullbox_header(&infe_payload, 3U);
    append_u32be(&infe_payload, kPrimaryItemId);
    append_u16be(&infe_payload, 0U);
    append_fourcc(&infe_payload, openmeta::fourcc('h', 'v', 'c', '1'));
    append_bytes(&infe_payload, "Primary");
    infe_payload.push_back(std::byte { 0x00 });
    std::vector<std::byte> infe_box;
    append_bmff_box(&infe_box, openmeta::fourcc('i', 'n', 'f', 'e'),
                    std::span<const std::byte>(infe_payload.data(),
                                               infe_payload.size()));

    std::vector<std::byte> iinf_payload;
    append_bmff_fullbox_header(&iinf_payload, 1U);
    append_u32be(&iinf_payload, 1U);
    iinf_payload.insert(iinf_payload.end(), infe_box.begin(), infe_box.end());
    std::vector<std::byte> iinf_box;
    append_bmff_box(&iinf_box, openmeta::fourcc('i', 'i', 'n', 'f'),
                    std::span<const std::byte>(iinf_payload.data(),
                                               iinf_payload.size()));

    std::vector<std::byte> iloc_payload;
    append_bmff_fullbox_header(&iloc_payload, 2U);
    iloc_payload.push_back(std::byte { 0x44 });
    iloc_payload.push_back(std::byte { 0x40 });
    append_u32be(&iloc_payload, 1U);
    append_u32be(&iloc_payload, kPrimaryItemId);
    append_u16be(&iloc_payload, 0x0001U);
    append_u16be(&iloc_payload, 0U);
    append_u32be(&iloc_payload, 0U);
    append_u16be(&iloc_payload, 1U);
    append_u32be(&iloc_payload, 0U);
    append_u32be(&iloc_payload, 1U);
    std::vector<std::byte> iloc_box;
    append_bmff_box(&iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(iloc_payload.data(),
                                               iloc_payload.size()));

    const std::array<std::byte, 1> image_payload = { std::byte { 0xAA } };
    std::vector<std::byte> idat_box;
    append_bmff_box(&idat_box, openmeta::fourcc('i', 'd', 'a', 't'),
                    std::span<const std::byte>(image_payload.data(),
                                               image_payload.size()));

    std::vector<std::byte> meta_payload;
    append_bmff_fullbox_header(&meta_payload, 0U);
    meta_payload.insert(meta_payload.end(), pitm_box.begin(), pitm_box.end());
    meta_payload.insert(meta_payload.end(), iinf_box.begin(), iinf_box.end());
    meta_payload.insert(meta_payload.end(), iloc_box.begin(), iloc_box.end());
    meta_payload.insert(meta_payload.end(), idat_box.begin(), idat_box.end());

    std::vector<std::byte> meta_box;
    append_bmff_box(&meta_box, openmeta::fourcc('m', 'e', 't', 'a'),
                    std::span<const std::byte>(meta_payload.data(),
                                               meta_payload.size()));
    out.insert(out.end(), meta_box.begin(), meta_box.end());
    return out;
}

