static bool
build_test_target_with_existing_creator_tool_xmp(
    openmeta::TransferTargetFormat format, std::string_view creator_tool,
    std::vector<std::byte>* out)
{
    if (!out) {
        return false;
    }
    out->clear();

    if (format == openmeta::TransferTargetFormat::Jpeg) {
        std::vector<std::byte> payload;
        if (!build_test_creator_tool_jpeg_xmp_app1_payload(creator_tool,
                                                           &payload)) {
            return false;
        }
        const TestJpegSegment segments[] = {
            { 0xE1U,
              std::span<const std::byte>(payload.data(), payload.size()) },
        };
        *out = make_jpeg_with_segments(
            std::span<const TestJpegSegment>(segments, 1U));
        return true;
    }

    if (format == openmeta::TransferTargetFormat::Tiff
        || format == openmeta::TransferTargetFormat::Dng) {
        return build_test_tiff_with_creator_tool_xmp(creator_tool, out);
    }

    std::vector<std::byte> packet;
    if (!build_test_creator_tool_xmp_sidecar(creator_tool, &packet)) {
        return false;
    }

    if (format == openmeta::TransferTargetFormat::Png) {
        std::vector<std::byte> metadata;
        std::vector<std::byte> payload;
        if (!build_test_creator_tool_png_xmp_itxt_payload(creator_tool,
                                                          &payload)) {
            return false;
        }
        append_png_chunk(&metadata, openmeta::fourcc('i', 'T', 'X', 't'),
                         std::span<const std::byte>(payload.data(),
                                                    payload.size()));
        *out = build_minimal_png_file(
            std::span<const std::byte>(metadata.data(), metadata.size()));
        return true;
    }

    if (format == openmeta::TransferTargetFormat::Webp) {
        std::vector<std::byte> metadata;
        append_webp_chunk(&metadata, openmeta::fourcc('X', 'M', 'P', ' '),
                          std::span<const std::byte>(packet.data(),
                                                     packet.size()));
        *out = build_minimal_webp_file(
            std::span<const std::byte>(metadata.data(), metadata.size()),
            0x04U);
        return true;
    }

    if (format == openmeta::TransferTargetFormat::Jp2) {
        std::vector<std::byte> metadata;
        append_jp2_box(&metadata, openmeta::fourcc('x', 'm', 'l', ' '),
                       std::span<const std::byte>(packet.data(), packet.size()));
        *out = build_minimal_jp2_file(
            std::span<const std::byte>(metadata.data(), metadata.size()));
        return true;
    }

    if (format == openmeta::TransferTargetFormat::Jxl) {
        *out = make_minimal_jxl_file();
        append_bmff_box(out, openmeta::fourcc('x', 'm', 'l', ' '),
                        std::span<const std::byte>(packet.data(),
                                                   packet.size()));
        return true;
    }

    if (format == openmeta::TransferTargetFormat::Heif
        || format == openmeta::TransferTargetFormat::Avif
        || format == openmeta::TransferTargetFormat::Cr3) {
        std::vector<std::byte> input;
        if (format == openmeta::TransferTargetFormat::Heif) {
            input = make_minimal_heif_file();
        } else if (format == openmeta::TransferTargetFormat::Avif) {
            input = make_minimal_avif_file();
        } else {
            input = make_minimal_cr3_file();
        }

        openmeta::PreparedTransferBundle bundle;
        bundle.target_format = format;

        openmeta::PreparedTransferBlock xmp;
        xmp.kind    = openmeta::TransferBlockKind::Xmp;
        xmp.order   = 100U;
        xmp.route   = "bmff:item-xmp";
        xmp.payload = packet;
        bundle.blocks.push_back(std::move(xmp));

        openmeta::ExecutePreparedTransferOptions options;
        options.edit_requested = true;
        options.edit_apply     = true;

        const openmeta::ExecutePreparedTransferResult result
            = openmeta::execute_prepared_transfer(
                &bundle, std::span<const std::byte>(input.data(), input.size()),
                options);
        if (result.edit_apply.status != openmeta::TransferStatus::Ok
            || result.edited_output.empty()) {
            return false;
        }
        *out = result.edited_output;
        return true;
    }

    return false;
}

static bool
build_test_target_with_foreign_bmff_creator_tool_xmp(
    openmeta::TransferTargetFormat format, std::string_view creator_tool,
    std::vector<std::byte>* out)
{
    if (!out) {
        return false;
    }
    out->clear();
    if (format != openmeta::TransferTargetFormat::Heif
        && format != openmeta::TransferTargetFormat::Avif
        && format != openmeta::TransferTargetFormat::Cr3) {
        return false;
    }

    if (!build_test_target_with_existing_creator_tool_xmp(format, creator_tool,
                                                          out)) {
        return false;
    }

    size_t box_off = 0U;
    while (box_off + 8U <= out->size()) {
        uint32_t size = 0U;
        uint32_t type = 0U;
        if (!read_test_u32be(std::span<const std::byte>(out->data(),
                                                        out->size()),
                             box_off, &size)
            || !read_test_u32be(std::span<const std::byte>(out->data(),
                                                           out->size()),
                                box_off + 4U, &type)) {
            return false;
        }
        if (size < 8U || box_off + size > out->size()) {
            return false;
        }
        if (type == openmeta::fourcc('m', 'e', 't', 'a')) {
            if (size < 12U) {
                return false;
            }
            const size_t child_begin = box_off + 12U;
            size_t child_off         = child_begin;
            while (child_off + 8U <= box_off + size) {
                uint32_t child_size = 0U;
                uint32_t child_type = 0U;
                if (!read_test_u32be(std::span<const std::byte>(out->data(),
                                                                out->size()),
                                     child_off, &child_size)
                    || !read_test_u32be(std::span<const std::byte>(out->data(),
                                                                   out->size()),
                                        child_off + 4U, &child_type)) {
                    return false;
                }
                if (child_size < 8U
                    || child_off + child_size > box_off + size) {
                    return false;
                }
                if (child_type == openmeta::fourcc('u', 'u', 'i', 'd')
                    && child_size >= 24U) {
                    (*out)[child_off + 8U] ^= std::byte { 0x01 };
                    return true;
                }
                child_off += child_size;
            }
            return false;
        }
        box_off += size;
    }
    return false;
}

static bool
build_test_target_with_foreign_bmff_iinf_v2_creator_tool_xmp(
    openmeta::TransferTargetFormat format, std::string_view creator_tool,
    std::vector<std::byte>* out)
{
    if (!out) {
        return false;
    }
    if (format == openmeta::TransferTargetFormat::Heif) {
        *out = make_minimal_heif_file();
    } else if (format == openmeta::TransferTargetFormat::Avif) {
        *out = make_minimal_avif_file();
    } else if (format == openmeta::TransferTargetFormat::Cr3) {
        *out = make_minimal_cr3_file();
    } else {
        out->clear();
        return false;
    }

    std::vector<std::byte> packet;
    if (!build_test_creator_tool_xmp_sidecar(creator_tool, &packet)) {
        return false;
    }

    std::vector<std::byte> infe_payload;
    append_bmff_fullbox_header(&infe_payload, 2U);
    append_u16be(&infe_payload, 1U);
    append_u16be(&infe_payload, 0U);
    append_fourcc(&infe_payload, openmeta::fourcc('m', 'i', 'm', 'e'));
    append_bytes(&infe_payload, "XMP");
    infe_payload.push_back(std::byte { 0x00 });
    append_bytes(&infe_payload, "application/rdf+xml");
    infe_payload.push_back(std::byte { 0x00 });
    infe_payload.push_back(std::byte { 0x00 });

    std::vector<std::byte> infe_box;
    append_bmff_box(&infe_box, openmeta::fourcc('i', 'n', 'f', 'e'),
                    std::span<const std::byte>(infe_payload.data(),
                                               infe_payload.size()));

    std::vector<std::byte> iinf_payload;
    append_bmff_fullbox_header(&iinf_payload, 2U);
    append_u32be(&iinf_payload, 1U);
    iinf_payload.insert(iinf_payload.end(), infe_box.begin(), infe_box.end());

    std::vector<std::byte> iinf_box;
    append_bmff_box(&iinf_box, openmeta::fourcc('i', 'i', 'n', 'f'),
                    std::span<const std::byte>(iinf_payload.data(),
                                               iinf_payload.size()));

    std::vector<std::byte> idat_box;
    append_bmff_box(&idat_box, openmeta::fourcc('i', 'd', 'a', 't'),
                    std::span<const std::byte>(packet.data(), packet.size()));

    std::vector<std::byte> iloc_payload;
    append_bmff_fullbox_header(&iloc_payload, 1U);
    iloc_payload.push_back(std::byte { 0x44 });
    iloc_payload.push_back(std::byte { 0x00 });
    append_u16be(&iloc_payload, 1U);
    append_u16be(&iloc_payload, 1U);
    append_u16be(&iloc_payload, 1U);
    append_u16be(&iloc_payload, 0U);
    append_u16be(&iloc_payload, 1U);
    append_u32be(&iloc_payload, 0U);
    append_u32be(&iloc_payload, static_cast<uint32_t>(packet.size()));

    std::vector<std::byte> iloc_box;
    append_bmff_box(&iloc_box, openmeta::fourcc('i', 'l', 'o', 'c'),
                    std::span<const std::byte>(iloc_payload.data(),
                                               iloc_payload.size()));

    std::vector<std::byte> meta_payload;
    append_bmff_fullbox_header(&meta_payload, 0U);
    meta_payload.insert(meta_payload.end(), iinf_box.begin(), iinf_box.end());
    meta_payload.insert(meta_payload.end(), iloc_box.begin(), iloc_box.end());
    meta_payload.insert(meta_payload.end(), idat_box.begin(), idat_box.end());

    std::vector<std::byte> meta_box;
    append_bmff_box(&meta_box, openmeta::fourcc('m', 'e', 't', 'a'),
                    std::span<const std::byte>(meta_payload.data(),
                                               meta_payload.size()));
    out->insert(out->end(), meta_box.begin(), meta_box.end());
    return true;
}

static bool
store_has_text_entry(const openmeta::MetaStore& store,
                     const openmeta::MetaKeyView& key,
                     std::string_view expected) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U) {
        return false;
    }
    return arena_text(store, store.entry(ids[0])) == expected;
}

static bool
store_has_any_text_entry(const openmeta::MetaStore& store,
                         const openmeta::MetaKeyView& key,
                         std::string_view expected) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    for (const openmeta::EntryId id : ids) {
        if (arena_text(store, store.entry(id)) == expected) {
            return true;
        }
    }
    return false;
}

static bool
store_has_bytes_entry(const openmeta::MetaStore& store,
                      const openmeta::MetaKeyView& key,
                      std::span<const std::byte> expected) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    if (entry.value.kind != openmeta::MetaValueKind::Bytes) {
        return false;
    }
    const std::span<const std::byte> actual = store.arena().span(
        entry.value.data.span);
    return actual.size() == expected.size()
           && std::equal(actual.begin(), actual.end(), expected.begin());
}

static bool
store_has_u32_scalar_entry(const openmeta::MetaStore& store,
                           const openmeta::MetaKeyView& key,
                           uint64_t expected) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    return entry.value.kind == openmeta::MetaValueKind::Scalar
           && entry.value.elem_type == openmeta::MetaElementType::U32
           && entry.value.data.u64 == expected;
}

static bool
store_has_u16_scalar_entry(const openmeta::MetaStore& store,
                           const openmeta::MetaKeyView& key,
                           uint16_t expected) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    return entry.value.kind == openmeta::MetaValueKind::Scalar
           && entry.value.elem_type == openmeta::MetaElementType::U16
           && entry.value.data.u64 == expected;
}

static bool
store_read_tiff_u16_scalar(const openmeta::MetaStore& store,
                           const openmeta::MetaKeyView& key,
                           uint16_t* out_value) noexcept
{
    if (out_value) {
        *out_value = 0U;
    }
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    if (entry.origin.wire_type.family != openmeta::WireFamily::Tiff
        || entry.origin.wire_type.code != 3U
        || entry.value.kind != openmeta::MetaValueKind::Scalar
        || entry.value.count != 1U) {
        return false;
    }
    uint64_t value = 0U;
    switch (entry.value.elem_type) {
    case openmeta::MetaElementType::U8:
    case openmeta::MetaElementType::U16:
    case openmeta::MetaElementType::U32:
    case openmeta::MetaElementType::U64: value = entry.value.data.u64; break;
    default: return false;
    }
    if (value > std::numeric_limits<uint16_t>::max()) {
        return false;
    }
    if (out_value) {
        *out_value = static_cast<uint16_t>(value);
    }
    return true;
}

static bool
store_has_u8_scalar_entry(const openmeta::MetaStore& store,
                          const openmeta::MetaKeyView& key,
                          uint8_t expected) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    return entry.value.kind == openmeta::MetaValueKind::Scalar
           && entry.value.elem_type == openmeta::MetaElementType::U8
           && entry.value.data.u64 == expected;
}

static bool
store_has_urational_scalar_entry(const openmeta::MetaStore& store,
                                 const openmeta::MetaKeyView& key,
                                 uint32_t numerator,
                                 uint32_t denominator) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U || denominator == 0U) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    return entry.value.kind == openmeta::MetaValueKind::Scalar
           && entry.value.elem_type == openmeta::MetaElementType::URational
           && entry.value.data.ur.denom != 0U
           && static_cast<uint64_t>(entry.value.data.ur.numer) * denominator
                  == static_cast<uint64_t>(numerator)
                         * entry.value.data.ur.denom;
}

static bool
store_has_srational_scalar_entry(const openmeta::MetaStore& store,
                                 const openmeta::MetaKeyView& key,
                                 int32_t numerator,
                                 int32_t denominator) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U || denominator <= 0) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    return entry.value.kind == openmeta::MetaValueKind::Scalar
           && entry.value.elem_type == openmeta::MetaElementType::SRational
           && entry.value.data.sr.denom > 0
           && static_cast<int64_t>(entry.value.data.sr.numer) * denominator
                  == static_cast<int64_t>(numerator)
                         * entry.value.data.sr.denom;
}

static bool
store_has_urational_array_entry(
    const openmeta::MetaStore& store, const openmeta::MetaKeyView& key,
    std::span<const openmeta::URational> expected) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    if (entry.value.kind != openmeta::MetaValueKind::Array
        || entry.value.elem_type != openmeta::MetaElementType::URational
        || entry.value.count != expected.size()) {
        return false;
    }
    const std::span<const std::byte> raw = store.arena().span(
        entry.value.data.span);
    if (raw.size() != expected.size() * sizeof(openmeta::URational)) {
        return false;
    }
    for (size_t i = 0U; i < expected.size(); ++i) {
        openmeta::URational actual;
        std::memcpy(&actual, raw.data() + i * sizeof(actual), sizeof(actual));
        if (actual.numer != expected[i].numer
            || actual.denom != expected[i].denom) {
            return false;
        }
    }
    return true;
}

static bool
add_dirty_exififd_entry(openmeta::MetaStore& store, uint16_t tag,
                        openmeta::MetaValue value) noexcept
{
    openmeta::Entry entry;
    entry.key   = openmeta::make_exif_tag_key(store.arena(), "exififd", tag);
    entry.value = value;
    entry.flags = openmeta::EntryFlags::Dirty;
    return store.add_entry(entry) != openmeta::kInvalidEntryId;
}

static bool
store_has_u8_array_entry(const openmeta::MetaStore& store,
                         const openmeta::MetaKeyView& key,
                         std::span<const uint8_t> expected) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    if (entry.value.kind != openmeta::MetaValueKind::Array
        || entry.value.elem_type != openmeta::MetaElementType::U8
        || entry.value.count != expected.size()) {
        return false;
    }
    const std::span<const std::byte> raw = store.arena().span(
        entry.value.data.span);
    if (raw.size() != expected.size()) {
        return false;
    }
    for (size_t i = 0; i < expected.size(); ++i) {
        if (std::to_integer<uint8_t>(raw[i]) != expected[i]) {
            return false;
        }
    }
    return true;
}

static bool
store_has_u16_array_entry(const openmeta::MetaStore& store,
                          const openmeta::MetaKeyView& key,
                          std::span<const uint16_t> expected) noexcept
{
    const std::span<const openmeta::EntryId> ids = store.find_all(key);
    if (ids.size() != 1U) {
        return false;
    }
    const openmeta::Entry& entry = store.entry(ids[0]);
    if (entry.value.kind != openmeta::MetaValueKind::Array
        || entry.value.elem_type != openmeta::MetaElementType::U16
        || entry.value.count != expected.size()) {
        return false;
    }
    const std::span<const std::byte> raw = store.arena().span(
        entry.value.data.span);
    if (raw.size() != expected.size() * sizeof(uint16_t)) {
        return false;
    }
    for (size_t i = 0; i < expected.size(); ++i) {
        uint16_t actual = 0U;
        std::memcpy(&actual, raw.data() + i * sizeof(uint16_t),
                    sizeof(uint16_t));
        if (actual != expected[i]) {
            return false;
        }
    }
    return true;
}

static bool
add_dirty_tiff_spatial_entries(
    openmeta::MetaStore& store, openmeta::URational focal_plane_x,
    openmeta::URational focal_plane_y, uint16_t resolution_unit,
    std::span<const uint16_t> subject_area,
    std::span<const uint16_t> subject_location) noexcept
{
    return add_dirty_exififd_entry(
               store, 0xA20EU,
               openmeta::make_urational(focal_plane_x.numer,
                                        focal_plane_x.denom))
           && add_dirty_exififd_entry(
               store, 0xA20FU,
               openmeta::make_urational(focal_plane_y.numer,
                                        focal_plane_y.denom))
           && add_dirty_exififd_entry(store, 0xA210U,
                                      openmeta::make_u16(resolution_unit))
           && add_dirty_exififd_entry(
               store, 0x9214U,
               openmeta::make_u16_array(store.arena(), subject_area))
           && add_dirty_exififd_entry(
               store, 0xA214U,
               openmeta::make_u16_array(store.arena(), subject_location));
}

static bool
decode_transfer_roundtrip_store(std::span<const std::byte> bytes,
                                openmeta::MetaStore* out,
                                bool decode_makernote = false) noexcept
{
    if (!out) {
        return false;
    }
    *out = openmeta::MetaStore {};
    std::array<openmeta::ContainerBlockRef, 32> blocks {};
    std::array<openmeta::ExifIfdRef, 32> ifds {};
    std::array<std::byte, 8192> payload {};
    std::array<uint32_t, 128> payload_parts {};
    openmeta::SimpleMetaDecodeOptions decode_options;
    decode_options.exif.decode_makernote = decode_makernote;

    const openmeta::SimpleMetaResult read
        = openmeta::simple_meta_read(bytes, *out, blocks, ifds, payload,
                                     payload_parts, decode_options);
    if (read.scan.status != openmeta::ScanStatus::Ok
        && read.xmp.status != openmeta::XmpDecodeStatus::Ok) {
        return false;
    }

    out->finalize();
    return true;
}

static bool
decoded_transfer_roundtrip_has_expected_fields(
    std::span<const std::byte> bytes) noexcept
{
    openmeta::MetaStore decoded;
    if (!decode_transfer_roundtrip_store(bytes, &decoded)) {
        return false;
    }

    return store_has_text_entry(decoded, exif_key_view("exififd", 0x9003U),
                                "2024:01:02 03:04:05")
           && store_has_text_entry(decoded,
                                   xmp_key_view("http://ns.adobe.com/xap/1.0/",
                                                "CreatorTool"),
                                   "OpenMeta Transfer Source");
}

static bool
decoded_transfer_roundtrip_has_target_image_spec_fields(
    std::span<const std::byte> bytes) noexcept
{
    openmeta::MetaStore decoded;
    if (!decode_transfer_roundtrip_store(bytes, &decoded)) {
        return false;
    }

    const std::array<uint16_t, 3> bits          = { 8U, 8U, 8U };
    const std::array<uint16_t, 3> sample_format = { 1U, 1U, 1U };
    return store_has_u32_scalar_entry(decoded, exif_key_view("ifd0", 0x0100U),
                                      320U)
           && store_has_u32_scalar_entry(decoded,
                                         exif_key_view("ifd0", 0x0101U), 240U)
           && store_has_u32_scalar_entry(decoded,
                                         exif_key_view("exififd", 0xA002U),
                                         320U)
           && store_has_u32_scalar_entry(decoded,
                                         exif_key_view("exififd", 0xA003U),
                                         240U)
           && store_has_u16_scalar_entry(decoded,
                                         exif_key_view("ifd0", 0x0112U), 1U)
           && store_has_u16_scalar_entry(decoded,
                                         exif_key_view("ifd0", 0x0115U), 3U)
           && store_has_u16_array_entry(decoded, exif_key_view("ifd0", 0x0102U),
                                        std::span<const uint16_t>(bits.data(),
                                                                  bits.size()))
           && store_has_u16_scalar_entry(decoded,
                                         exif_key_view("ifd0", 0x0106U), 2U)
           && store_has_u16_scalar_entry(decoded,
                                         exif_key_view("ifd0", 0x011CU), 1U)
           && store_has_u16_array_entry(
               decoded, exif_key_view("ifd0", 0x0153U),
               std::span<const uint16_t>(sample_format.data(),
                                         sample_format.size()))
           && store_has_u16_scalar_entry(decoded,
                                         exif_key_view("exififd", 0xA001U), 1U);
}

static bool
build_rendered_image_safety_source_store(openmeta::MetaStore* store)
{
    if (!store) {
        return false;
    }
    *store                        = openmeta::MetaStore {};
    const openmeta::BlockId block = store->add_block(openmeta::BlockInfo {});
    if (block == openmeta::kInvalidBlockId) {
        return false;
    }

    openmeta::Entry make;
    make.key   = openmeta::make_exif_tag_key(store->arena(), "ifd0", 0x010FU);
    make.value = openmeta::make_text(store->arena(), "CameraVendor",
                                     openmeta::TextEncoding::Ascii);
    make.origin.block          = block;
    make.origin.order_in_block = 0U;
    if (store->add_entry(make) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry datetime_original;
    datetime_original.key = openmeta::make_exif_tag_key(store->arena(),
                                                        "exififd", 0x9003U);
    datetime_original.value
        = openmeta::make_text(store->arena(), "2024:01:02 03:04:05",
                              openmeta::TextEncoding::Ascii);
    datetime_original.origin.block          = block;
    datetime_original.origin.order_in_block = 1U;
    if (store->add_entry(datetime_original) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry stale_width;
    stale_width.key   = openmeta::make_exif_tag_key(store->arena(), "ifd0",
                                                    0x0100U);
    stale_width.value = openmeta::make_u32(999U);
    stale_width.origin.block          = block;
    stale_width.origin.order_in_block = 2U;
    if (store->add_entry(stale_width) == openmeta::kInvalidEntryId) {
        return false;
    }

    const std::array<openmeta::SRational, 9> color_matrix = {
        openmeta::SRational { 1, 1 }, openmeta::SRational { 0, 1 },
        openmeta::SRational { 0, 1 }, openmeta::SRational { 0, 1 },
        openmeta::SRational { 1, 1 }, openmeta::SRational { 0, 1 },
        openmeta::SRational { 0, 1 }, openmeta::SRational { 0, 1 },
        openmeta::SRational { 1, 1 },
    };
    openmeta::Entry raw_color;
    raw_color.key   = openmeta::make_exif_tag_key(store->arena(), "ifd0",
                                                  0xC621U);
    raw_color.value = openmeta::make_srational_array(
        store->arena(),
        std::span<const openmeta::SRational>(color_matrix.data(),
                                             color_matrix.size()));
    raw_color.origin.block          = block;
    raw_color.origin.order_in_block = 3U;
    if (store->add_entry(raw_color) == openmeta::kInvalidEntryId) {
        return false;
    }

    const std::array<std::byte, 4> raw_digest_bytes = {
        std::byte { 0x10 },
        std::byte { 0x20 },
        std::byte { 0x30 },
        std::byte { 0x40 },
    };
    openmeta::Entry raw_digest;
    raw_digest.key   = openmeta::make_exif_tag_key(store->arena(), "ifd0",
                                                   0xC71CU);
    raw_digest.value = openmeta::make_bytes(
        store->arena(), std::span<const std::byte>(raw_digest_bytes.data(),
                                                   raw_digest_bytes.size()));
    raw_digest.origin.block          = block;
    raw_digest.origin.order_in_block = 4U;
    if (store->add_entry(raw_digest) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry raw_preview_gain;
    raw_preview_gain.key   = openmeta::make_exif_tag_key(store->arena(), "ifd0",
                                                         0xC7A8U);
    raw_preview_gain.value = openmeta::make_u32(2U);
    raw_preview_gain.origin.block          = block;
    raw_preview_gain.origin.order_in_block = 5U;
    if (store->add_entry(raw_preview_gain) == openmeta::kInvalidEntryId) {
        return false;
    }

    const std::vector<std::byte> vendor_private_bytes = ascii_z(
        "SOURCE_VENDOR_PRIVATE_DROP");
    openmeta::Entry vendor_private;
    vendor_private.key   = openmeta::make_exif_tag_key(store->arena(),
                                                       "mk_sony_sr2private_0",
                                                       0x7200U);
    vendor_private.value = openmeta::make_bytes(
        store->arena(),
        std::span<const std::byte>(vendor_private_bytes.data(),
                                   vendor_private_bytes.size()));
    vendor_private.origin.block          = block;
    vendor_private.origin.order_in_block = 6U;
    if (store->add_entry(vendor_private) == openmeta::kInvalidEntryId) {
        return false;
    }

    const std::vector<std::byte> makernote_bytes = ascii_z(
        "SOURCE_MAKERNOTE_DROP");
    openmeta::Entry makernote;
    makernote.key   = openmeta::make_exif_tag_key(store->arena(), "exififd",
                                                  0x927CU);
    makernote.value = openmeta::make_bytes(
        store->arena(), std::span<const std::byte>(makernote_bytes.data(),
                                                   makernote_bytes.size()));
    makernote.origin.block          = block;
    makernote.origin.order_in_block = 7U;
    if (store->add_entry(makernote) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry creator_tool;
    creator_tool.key = openmeta::make_xmp_property_key(
        store->arena(), "http://ns.adobe.com/xap/1.0/", "CreatorTool");
    creator_tool.value = openmeta::make_text(store->arena(), "OpenMeta Tool",
                                             openmeta::TextEncoding::Utf8);
    creator_tool.origin.block          = block;
    creator_tool.origin.order_in_block = 8U;
    if (store->add_entry(creator_tool) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry crs_exposure;
    crs_exposure.key = openmeta::make_xmp_property_key(
        store->arena(), "http://ns.adobe.com/camera-raw-settings/1.0/",
        "Exposure2012");
    crs_exposure.value        = openmeta::make_text(store->arena(), "+0.35",
                                                    openmeta::TextEncoding::Utf8);
    crs_exposure.origin.block = block;
    crs_exposure.origin.order_in_block = 9U;
    if (store->add_entry(crs_exposure) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry dng_profile_name;
    dng_profile_name.key = openmeta::make_xmp_property_key(
        store->arena(), "http://ns.adobe.com/dng/1.0/", "ProfileName");
    dng_profile_name.value                 = openmeta::make_text(store->arena(),
                                                                 "Source Raw Profile",
                                                                 openmeta::TextEncoding::Utf8);
    dng_profile_name.origin.block          = block;
    dng_profile_name.origin.order_in_block = 10U;
    if (store->add_entry(dng_profile_name) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry jumbf;
    jumbf.key          = openmeta::make_jumbf_cbor_key(store->arena(),
                                                       "box.0.1.cbor.manifest.label");
    jumbf.value        = openmeta::make_text(store->arena(), "source-manifest",
                                             openmeta::TextEncoding::Utf8);
    jumbf.origin.block = block;
    jumbf.origin.order_in_block = 11U;
    if (store->add_entry(jumbf) == openmeta::kInvalidEntryId) {
        return false;
    }

    store->finalize();
    return true;
}

static void
expect_rendered_image_safety_output(std::span<const std::byte> bytes)
{
    EXPECT_TRUE(payload_contains_ascii(bytes, "CameraVendor"));
    EXPECT_TRUE(payload_contains_ascii(bytes, "2024:01:02 03:04:05"));
    EXPECT_TRUE(payload_contains_ascii(bytes, "OpenMeta Tool"));
    EXPECT_FALSE(payload_contains_ascii(bytes, "Exposure2012"));
    EXPECT_FALSE(payload_contains_ascii(bytes, "Source Raw Profile"));
    EXPECT_FALSE(payload_contains_ascii(bytes, "SOURCE_MAKERNOTE_DROP"));
    EXPECT_FALSE(payload_contains_ascii(bytes, "SOURCE_VENDOR_PRIVATE_DROP"));

    openmeta::MetaStore decoded;
    ASSERT_TRUE(decode_transfer_roundtrip_store(bytes, &decoded));
    EXPECT_TRUE(store_has_text_entry(decoded, exif_key_view("ifd0", 0x010FU),
                                     "CameraVendor"));
    EXPECT_TRUE(store_has_text_entry(decoded, exif_key_view("exififd", 0x9003U),
                                     "2024:01:02 03:04:05"));
    EXPECT_TRUE(store_has_text_entry(
        decoded, xmp_key_view("http://ns.adobe.com/xap/1.0/", "CreatorTool"),
        "OpenMeta Tool"));
    EXPECT_EQ(decoded.find_all(exif_key_view("ifd0", 0x0100U)).size(), 0U);
    EXPECT_EQ(decoded.find_all(exif_key_view("ifd0", 0xC621U)).size(), 0U);
    EXPECT_EQ(decoded.find_all(exif_key_view("ifd0", 0xC71CU)).size(), 0U);
    EXPECT_EQ(decoded.find_all(exif_key_view("ifd0", 0xC7A8U)).size(), 0U);
    EXPECT_EQ(decoded.find_all(exif_key_view("exififd", 0x927CU)).size(), 0U);
    EXPECT_EQ(decoded
                  .find_all(xmp_key_view(
                      "http://ns.adobe.com/camera-raw-settings/1.0/",
                      "Exposure2012"))
                  .size(),
              0U);
}

struct SnapshotExecuteThreadState final {
    const openmeta::TransferSourceSnapshot* snapshot = nullptr;
    openmeta::ExecutePreparedTransferSnapshotOptions options;
    openmeta::ExecutePreparedTransferFileResult result;
};

static void
run_snapshot_execute_thread(SnapshotExecuteThreadState* state)
{
    if (!state || !state->snapshot) {
        return;
    }
    state->result
        = openmeta::execute_prepared_transfer_snapshot(*state->snapshot,
                                                       state->options);
}

static bool
store_lacks_text_entry(const openmeta::MetaStore& store,
                       const openmeta::MetaKeyView& key) noexcept
{
    return store.find_all(key).empty();
}

static void
expect_tiff_family_preview_aux_structure(std::span<const std::byte> bytes,
                                         bool expect_embedded_xmp_tag)
{
    const uint32_t ifd0_off = read_u32le(bytes, 4U);
    ASSERT_NE(ifd0_off, 0U);

    uint32_t ignored_value = 0U;
    if (expect_embedded_xmp_tag) {
        EXPECT_TRUE(find_tiff_tag_entry_le(bytes, ifd0_off, 700U, nullptr,
                                           nullptr, &ignored_value));
    } else {
        EXPECT_FALSE(find_tiff_tag_entry_le(bytes, ifd0_off, 700U, nullptr,
                                            nullptr, &ignored_value));
    }

    const uint16_t ifd0_count = read_u16le(bytes,
                                           static_cast<size_t>(ifd0_off));
    const uint32_t ifd1_off
        = read_u32le(bytes, static_cast<size_t>(ifd0_off) + 2U
                                + static_cast<size_t>(ifd0_count) * 12U);
    ASSERT_NE(ifd1_off, 0U);

    uint32_t ifd1_width = 0U;
    ASSERT_TRUE(find_tiff_tag_entry_le(bytes, ifd1_off, 0x0100U, nullptr,
                                       nullptr, &ifd1_width));
    EXPECT_EQ(ifd1_width, 111U);

    const uint16_t ifd1_count = read_u16le(bytes,
                                           static_cast<size_t>(ifd1_off));
    const uint32_t ifd1_next_off
        = read_u32le(bytes, static_cast<size_t>(ifd1_off) + 2U
                                + static_cast<size_t>(ifd1_count) * 12U);
    EXPECT_EQ(ifd1_next_off, 52U);

    uint32_t tail_ifd_width = 0U;
    ASSERT_TRUE(find_tiff_tag_entry_le(bytes, ifd1_next_off, 0x0100U, nullptr,
                                       nullptr, &tail_ifd_width));
    EXPECT_EQ(tail_ifd_width, 222U);

    uint32_t subifd_count     = 0U;
    uint32_t subifd_array_off = 0U;
    ASSERT_TRUE(find_tiff_tag_entry_le(bytes, ifd0_off, 0x014AU, nullptr,
                                       &subifd_count, &subifd_array_off));
    EXPECT_EQ(subifd_count, 2U);
    EXPECT_EQ(subifd_array_off, 26U);

    const uint32_t subifd0_off = read_u32le(bytes, subifd_array_off + 0U);
    const uint32_t subifd1_off = read_u32le(bytes, subifd_array_off + 4U);
    EXPECT_EQ(subifd0_off, 70U);
    EXPECT_EQ(subifd1_off, 88U);

    uint32_t subifd0_width = 0U;
    uint32_t subifd1_width = 0U;
    ASSERT_TRUE(find_tiff_tag_entry_le(bytes, subifd0_off, 0x0100U, nullptr,
                                       nullptr, &subifd0_width));
    ASSERT_TRUE(find_tiff_tag_entry_le(bytes, subifd1_off, 0x0100U, nullptr,
                                       nullptr, &subifd1_width));
    EXPECT_EQ(subifd0_width, 111U);
    EXPECT_EQ(subifd1_width, 777U);
}

static void
expect_tiff_family_preview_aux_xmp_absent_from_all_carriers(
    std::span<const std::byte> bytes)
{
    const uint32_t ifd0_off = read_u32le(bytes, 4U);
    ASSERT_NE(ifd0_off, 0U);

    uint32_t ignored_value = 0U;
    EXPECT_FALSE(find_tiff_tag_entry_le(bytes, ifd0_off, 700U, nullptr, nullptr,
                                        &ignored_value));

    const uint16_t ifd0_count = read_u16le(bytes,
                                           static_cast<size_t>(ifd0_off));
    const uint32_t ifd1_off
        = read_u32le(bytes, static_cast<size_t>(ifd0_off) + 2U
                                + static_cast<size_t>(ifd0_count) * 12U);
    ASSERT_NE(ifd1_off, 0U);
    EXPECT_FALSE(find_tiff_tag_entry_le(bytes, ifd1_off, 700U, nullptr, nullptr,
                                        &ignored_value));

    uint32_t subifd_count     = 0U;
    uint32_t subifd_array_off = 0U;
    ASSERT_TRUE(find_tiff_tag_entry_le(bytes, ifd0_off, 0x014AU, nullptr,
                                       &subifd_count, &subifd_array_off));
    for (uint32_t i = 0U; i < subifd_count; ++i) {
        const uint32_t subifd_off
            = read_u32le(bytes, subifd_array_off + static_cast<size_t>(i) * 4U);
        ASSERT_NE(subifd_off, 0U);
        EXPECT_FALSE(find_tiff_tag_entry_le(bytes, subifd_off, 700U, nullptr,
                                            nullptr, &ignored_value));
    }
}

static void
expect_bigtiff_preview_aux_structure(std::span<const std::byte> bytes,
                                     bool expect_embedded_xmp_tag)
{
    const uint64_t ifd0_off = read_u64le(bytes, 8U);
    ASSERT_NE(ifd0_off, 0U);

    uint64_t ignored_value = 0U;
    if (expect_embedded_xmp_tag) {
        EXPECT_TRUE(find_bigtiff_tag_entry_le(bytes, ifd0_off, 700U, nullptr,
                                              nullptr, &ignored_value));
    } else {
        EXPECT_FALSE(find_bigtiff_tag_entry_le(bytes, ifd0_off, 700U, nullptr,
                                               nullptr, &ignored_value));
    }

    const uint64_t ifd0_count = read_u64le(bytes,
                                           static_cast<size_t>(ifd0_off));
    const uint64_t ifd1_off
        = read_u64le(bytes, static_cast<size_t>(ifd0_off) + 8U
                                + static_cast<size_t>(ifd0_count) * 20U);
    ASSERT_NE(ifd1_off, 0U);

    uint64_t ifd1_width = 0U;
    ASSERT_TRUE(find_bigtiff_tag_entry_le(bytes, ifd1_off, 0x0100U, nullptr,
                                          nullptr, &ifd1_width));
    EXPECT_EQ(ifd1_width, 111U);

    const uint64_t ifd1_count = read_u64le(bytes,
                                           static_cast<size_t>(ifd1_off));
    const uint64_t ifd1_next_off
        = read_u64le(bytes, static_cast<size_t>(ifd1_off) + 8U
                                + static_cast<size_t>(ifd1_count) * 20U);
    ASSERT_NE(ifd1_next_off, 0U);

    uint64_t tail_ifd_width = 0U;
    ASSERT_TRUE(find_bigtiff_tag_entry_le(bytes, ifd1_next_off, 0x0100U,
                                          nullptr, nullptr, &tail_ifd_width));
    EXPECT_EQ(tail_ifd_width, 222U);

    uint64_t subifd_count     = 0U;
    uint64_t subifd_array_off = 0U;
    ASSERT_TRUE(find_bigtiff_tag_entry_le(bytes, ifd0_off, 0x014AU, nullptr,
                                          &subifd_count, &subifd_array_off));
    EXPECT_EQ(subifd_count, 2U);
    ASSERT_NE(subifd_array_off, 0U);

    const uint64_t subifd0_off
        = read_u64le(bytes, static_cast<size_t>(subifd_array_off) + 0U);
    const uint64_t subifd1_off
        = read_u64le(bytes, static_cast<size_t>(subifd_array_off) + 8U);
    ASSERT_NE(subifd0_off, 0U);
    ASSERT_NE(subifd1_off, 0U);

    uint64_t subifd0_width = 0U;
    uint64_t subifd1_width = 0U;
    ASSERT_TRUE(find_bigtiff_tag_entry_le(bytes, subifd0_off, 0x0100U, nullptr,
                                          nullptr, &subifd0_width));
    ASSERT_TRUE(find_bigtiff_tag_entry_le(bytes, subifd1_off, 0x0100U, nullptr,
                                          nullptr, &subifd1_width));
    EXPECT_EQ(subifd0_width, 111U);
    EXPECT_EQ(subifd1_width, 777U);
}

