    uint32_t ignored_value = 0U;
    EXPECT_FALSE(find_tiff_tag_entry_le(bytes, ifd0_off, 700U, nullptr, nullptr,
                                        &ignored_value));
    EXPECT_FALSE(find_tiff_tag_entry_le(bytes, exif_ifd_off, 700U, nullptr,
                                        nullptr, &ignored_value));

    uint32_t interop_ifd_off = 0U;
    const bool have_interop  = find_tiff_tag_entry_le(bytes, exif_ifd_off,
                                                      0xA005U, nullptr, nullptr,
                                                      &interop_ifd_off);
    EXPECT_EQ(have_interop, expect_interop_pointer);
