static uint64_t
read_tiff_test_unsigned(std::span<const std::byte> bytes, size_t offset,
                        size_t width, bool big_endian) noexcept
{
    uint64_t value = 0U;
    for (size_t i = 0U; i < width; ++i) {
        const size_t shift = big_endian ? (width - 1U - i) * 8U : i * 8U;
        value
            |= static_cast<uint64_t>(std::to_integer<uint8_t>(bytes[offset + i]))
               << shift;
    }
    return value;
}

static void
append_tiff_test_unsigned(std::vector<std::byte>* bytes, size_t width,
                          uint64_t value, bool big_endian)
{
    if (big_endian) {
        append_test_u_nbe(bytes, width, value);
        return;
    }
    for (size_t i = 0U; i < width; ++i) {
        bytes->push_back(static_cast<std::byte>((value >> (i * 8U)) & 0xFFU));
    }
}

static void
write_test_tiff_unsigned(std::vector<std::byte>* bytes, size_t offset,
                         size_t width, uint64_t value, bool big_endian) noexcept
{
    if (!bytes || offset > bytes->size() || width > bytes->size() - offset
        || width > sizeof(value)) {
        return;
    }
    for (size_t i = 0U; i < width; ++i) {
        const size_t shift   = big_endian ? (width - 1U - i) * 8U : i * 8U;
        (*bytes)[offset + i] = static_cast<std::byte>((value >> shift) & 0xFFU);
    }
}

static size_t
tiff_test_type_width(uint16_t type) noexcept
{
    switch (type) {
    case 1U:
    case 2U:
    case 6U:
    case 7U: return 1U;
    case 3U:
    case 8U: return 2U;
    case 4U:
    case 9U:
    case 11U:
    case 13U: return 4U;
    case 5U:
    case 10U:
    case 12U:
    case 16U:
    case 17U:
    case 18U: return 8U;
    default: return 0U;
    }
}

static bool
find_tiff_test_entry(std::span<const std::byte> bytes, uint64_t ifd_offset,
                     uint16_t tag, bool big_tiff, bool big_endian,
                     uint16_t* out_type, uint64_t* out_count,
                     uint64_t* out_value_or_offset) noexcept
{
    const size_t count_width  = big_tiff ? 8U : 2U;
    const size_t entry_width  = big_tiff ? 20U : 12U;
    const size_t inline_width = big_tiff ? 8U : 4U;
    const size_t next_width   = big_tiff ? 8U : 4U;
    if (ifd_offset > static_cast<uint64_t>(bytes.size())
        || count_width > bytes.size() - static_cast<size_t>(ifd_offset)) {
        return false;
    }
    const size_t base    = static_cast<size_t>(ifd_offset);
    const uint64_t count = read_tiff_test_unsigned(bytes, base, count_width,
                                                   big_endian);
    const size_t entries_offset = base + count_width;
    if (count > static_cast<uint64_t>(SIZE_MAX / entry_width)
        || count * static_cast<uint64_t>(entry_width)
               > bytes.size() - entries_offset
        || next_width > bytes.size() - entries_offset
                            - static_cast<size_t>(count) * entry_width) {
        return false;
    }
    for (size_t i = 0U; i < static_cast<size_t>(count); ++i) {
        const size_t entry_offset = entries_offset + i * entry_width;
        if (read_tiff_test_unsigned(bytes, entry_offset, 2U, big_endian)
            != tag) {
            continue;
        }
        const uint16_t type = static_cast<uint16_t>(
            read_tiff_test_unsigned(bytes, entry_offset + 2U, 2U, big_endian));
        const size_t count_field_width = big_tiff ? 8U : 4U;
        const uint64_t entry_count
            = read_tiff_test_unsigned(bytes, entry_offset + 4U,
                                      count_field_width, big_endian);
        const size_t type_width = tiff_test_type_width(type);
        if (type_width == 0U
            || entry_count > static_cast<uint64_t>(SIZE_MAX / type_width)) {
            return false;
        }
        if (out_type) {
            *out_type = type;
        }
        if (out_count) {
            *out_count = entry_count;
        }
        if (out_value_or_offset) {
            const size_t payload_size = static_cast<size_t>(entry_count)
                                        * type_width;
            const size_t value_offset = entry_offset + (big_tiff ? 12U : 8U);
            if (payload_size <= inline_width) {
                if (payload_size == 0U || payload_size > 8U) {
                    return false;
                }
                *out_value_or_offset
                    = read_tiff_test_unsigned(bytes, value_offset, payload_size,
                                              big_endian);
            } else {
                *out_value_or_offset
                    = read_tiff_test_unsigned(bytes, value_offset,
                                              big_tiff ? 8U : 4U, big_endian);
            }
        }
        return true;
    }
    return false;
}

struct ExpectedTiffScalar final {
    uint16_t tag;
    uint16_t type;
    int32_t numerator;
    uint32_t denominator;
};

static bool
add_dirty_tiff_scalars(openmeta::MetaStore& store,
                       std::span<const ExpectedTiffScalar> values) noexcept
{
    for (const ExpectedTiffScalar& expected : values) {
        openmeta::MetaValue value {};
        if (expected.type == 3U) {
            if (expected.numerator < 0
                || expected.numerator > std::numeric_limits<uint16_t>::max()) {
                return false;
            }
            value = openmeta::make_u16(
                static_cast<uint16_t>(expected.numerator));
        } else if (expected.type == 5U) {
            if (expected.numerator < 0 || expected.denominator == 0U) {
                return false;
            }
            value = openmeta::make_urational(static_cast<uint32_t>(
                                                 expected.numerator),
                                             expected.denominator);
        } else if (expected.type == 10U) {
            if (expected.denominator == 0U) {
                return false;
            }
            value = openmeta::make_srational(expected.numerator,
                                             static_cast<int32_t>(
                                                 expected.denominator));
        } else {
            return false;
        }
        if (!add_dirty_exififd_entry(store, expected.tag, value)) {
            return false;
        }
    }
    return true;
}

static void
expect_tiff_scalar_wire(std::span<const std::byte> bytes,
                        uint64_t exif_ifd_offset, bool big_tiff,
                        bool big_endian, size_t variant_index,
                        std::span<const ExpectedTiffScalar> expected_values)
{
    for (const ExpectedTiffScalar& expected : expected_values) {
        uint16_t type  = 0U;
        uint64_t count = 0U;
        uint64_t value = 0U;
        ASSERT_TRUE(find_tiff_test_entry(bytes, exif_ifd_offset, expected.tag,
                                         big_tiff, big_endian, &type, &count,
                                         &value))
            << "variant=" << variant_index << ", tag=" << expected.tag;
        EXPECT_EQ(type, expected.type)
            << "variant=" << variant_index << ", tag=" << expected.tag;
        EXPECT_EQ(count, 1U)
            << "variant=" << variant_index << ", tag=" << expected.tag;
        if (expected.type == 3U) {
            EXPECT_EQ(value, static_cast<uint16_t>(expected.numerator))
                << "variant=" << variant_index << ", tag=" << expected.tag;
            continue;
        }

        uint32_t numerator   = 0U;
        uint32_t denominator = 0U;
        if (big_tiff) {
            if (big_endian) {
                numerator   = static_cast<uint32_t>(value >> 32U);
                denominator = static_cast<uint32_t>(value & 0xFFFFFFFFULL);
            } else {
                numerator   = static_cast<uint32_t>(value & 0xFFFFFFFFULL);
                denominator = static_cast<uint32_t>(value >> 32U);
            }
        } else {
            if (value > static_cast<uint64_t>(bytes.size())
                || 8U > bytes.size() - static_cast<size_t>(value)) {
                ADD_FAILURE() << "rational value is out of range; variant="
                              << variant_index << ", tag=" << expected.tag;
                continue;
            }
            numerator = static_cast<uint32_t>(
                read_tiff_test_unsigned(bytes, static_cast<size_t>(value), 4U,
                                        big_endian));
            denominator = static_cast<uint32_t>(
                read_tiff_test_unsigned(bytes, static_cast<size_t>(value) + 4U,
                                        4U, big_endian));
        }
        EXPECT_EQ(numerator, static_cast<uint32_t>(expected.numerator))
            << "variant=" << variant_index << ", tag=" << expected.tag;
        EXPECT_EQ(denominator, expected.denominator)
            << "variant=" << variant_index << ", tag=" << expected.tag;
    }
}

static void
expect_tiff_scalar_store(const openmeta::MetaStore& store, size_t variant_index,
                         std::span<const ExpectedTiffScalar> expected_values)
{
    for (const ExpectedTiffScalar& expected : expected_values) {
        const openmeta::MetaKeyView key = exif_key_view("exififd",
                                                        expected.tag);
        if (expected.type == 3U) {
            EXPECT_TRUE(store_has_u16_scalar_entry(
                store, key, static_cast<uint16_t>(expected.numerator)))
                << "variant=" << variant_index << ", tag=" << expected.tag;
        } else if (expected.type == 5U) {
            EXPECT_TRUE(store_has_urational_scalar_entry(
                store, key, static_cast<uint32_t>(expected.numerator),
                expected.denominator))
                << "variant=" << variant_index << ", tag=" << expected.tag;
        } else {
            EXPECT_TRUE(store_has_srational_scalar_entry(
                store, key, expected.numerator,
                static_cast<int32_t>(expected.denominator)))
                << "variant=" << variant_index << ", tag=" << expected.tag;
        }
    }
}

static void
expect_tiff_capture_environment_wire(
    std::span<const std::byte> bytes, uint64_t exif_ifd_offset, bool big_tiff,
    bool big_endian, size_t variant_index,
    std::span<const ExpectedTiffScalar> expected_scalars,
    uint8_t expected_file_source, uint8_t expected_scene_type)
{
    expect_tiff_scalar_wire(bytes, exif_ifd_offset, big_tiff, big_endian,
                            variant_index, expected_scalars);
    struct ByteField final {
        uint16_t tag;
        uint8_t value;
    };
    const std::array<ByteField, 2U> byte_fields = { {
        { 0xA300U, expected_file_source },
        { 0xA301U, expected_scene_type },
    } };
    for (const ByteField& field : byte_fields) {
        uint16_t type  = 0U;
        uint64_t count = 0U;
        uint64_t value = 0U;
        ASSERT_TRUE(find_tiff_test_entry(bytes, exif_ifd_offset, field.tag,
                                         big_tiff, big_endian, &type, &count,
                                         &value))
            << "variant=" << variant_index << ", tag=" << field.tag;
        EXPECT_EQ(type, 7U) << "variant=" << variant_index
                            << ", tag=" << field.tag;
        EXPECT_EQ(count, 1U) << "variant=" << variant_index
                             << ", tag=" << field.tag;
        EXPECT_EQ(static_cast<uint8_t>(value & 0xFFU), field.value)
            << "variant=" << variant_index << ", tag=" << field.tag;
    }
}

static void
expect_tiff_capture_environment_store(
    const openmeta::MetaStore& store, size_t variant_index,
    std::span<const ExpectedTiffScalar> expected_scalars,
    uint8_t expected_file_source, uint8_t expected_scene_type)
{
    for (const ExpectedTiffScalar& expected : expected_scalars) {
        SCOPED_TRACE(variant_index);
        SCOPED_TRACE(expected.tag);
        const auto ids = store.find_all(exif_key_view("exififd", expected.tag));
        ASSERT_EQ(ids.size(), 1U);
        const openmeta::MetaValue& value = store.entry(ids[0U]).value;
        ASSERT_EQ(value.kind, openmeta::MetaValueKind::Scalar);
        ASSERT_EQ(value.count, 1U);
        if (expected.type == 3U) {
            ASSERT_EQ(value.elem_type, openmeta::MetaElementType::U16);
            EXPECT_EQ(value.data.u64,
                      static_cast<uint16_t>(expected.numerator));
        } else if (expected.type == 5U) {
            ASSERT_EQ(value.elem_type, openmeta::MetaElementType::URational);
            EXPECT_EQ(value.data.ur.numer,
                      static_cast<uint32_t>(expected.numerator));
            EXPECT_EQ(value.data.ur.denom, expected.denominator);
        } else {
            ASSERT_EQ(expected.type, 10U);
            ASSERT_EQ(value.elem_type, openmeta::MetaElementType::SRational);
            EXPECT_EQ(value.data.sr.numer, expected.numerator);
            EXPECT_EQ(value.data.sr.denom,
                      static_cast<int32_t>(expected.denominator));
        }
    }
    struct ByteField final {
        uint16_t tag;
        uint8_t value;
    };
    const std::array<ByteField, 2U> byte_fields = { {
        { 0xA300U, expected_file_source },
        { 0xA301U, expected_scene_type },
    } };
    for (const ByteField& field : byte_fields) {
        const std::span<const openmeta::EntryId> ids = store.find_all(
            exif_key_view("exififd", field.tag));
        ASSERT_EQ(ids.size(), 1U)
            << "variant=" << variant_index << ", tag=" << field.tag;
        const openmeta::Entry& entry = store.entry(ids[0U]);
        ASSERT_EQ(entry.value.kind, openmeta::MetaValueKind::Bytes)
            << "variant=" << variant_index << ", tag=" << field.tag;
        ASSERT_EQ(entry.value.count, 1U)
            << "variant=" << variant_index << ", tag=" << field.tag;
        const std::span<const std::byte> value = store.arena().span(
            entry.value.data.span);
        ASSERT_EQ(value.size(), 1U)
            << "variant=" << variant_index << ", tag=" << field.tag;
        EXPECT_EQ(std::to_integer<uint8_t>(value[0U]), field.value)
            << "variant=" << variant_index << ", tag=" << field.tag;
    }
}

static bool
find_tiff_test_exif_ifd(std::span<const std::byte> bytes, bool big_tiff,
                        bool big_endian, uint64_t* out_exif_ifd) noexcept
{
    if (!out_exif_ifd) {
        return false;
    }
    const size_t header_width = big_tiff ? 8U : 4U;
    const uint64_t ifd0_offset = read_tiff_test_unsigned(
        bytes, header_width, header_width, big_endian);
    return find_tiff_test_entry(bytes, ifd0_offset, 0x8769U, big_tiff,
                                big_endian, nullptr, nullptr, out_exif_ifd);
}

static void
expect_tiff_exif_tags_absent(std::span<const std::byte> bytes,
                             uint64_t exif_ifd_offset, bool big_tiff,
                             bool big_endian, size_t variant_index,
                             std::span<const uint16_t> tags)
{
    for (uint16_t tag : tags) {
        EXPECT_FALSE(find_tiff_test_entry(bytes, exif_ifd_offset, tag,
                                          big_tiff, big_endian, nullptr,
                                          nullptr, nullptr))
            << "variant=" << variant_index << ", tag=" << tag;
    }
}

static std::vector<std::byte>
make_tiff_test_unsigned(size_t width, uint64_t value, bool big_endian)
{
    std::vector<std::byte> encoded;
    append_tiff_test_unsigned(&encoded, width, value, big_endian);
    return encoded;
}

static void
append_tiff_test_entry(std::vector<std::byte>* tiff, uint16_t tag,
                       uint16_t type, uint64_t count, uint64_t value_or_offset,
                       std::span<const std::byte> inline_payload, bool big_tiff,
                       bool big_endian)
{
    const size_t inline_width = big_tiff ? 8U : 4U;
    append_tiff_test_unsigned(tiff, 2U, tag, big_endian);
    append_tiff_test_unsigned(tiff, 2U, type, big_endian);
    append_tiff_test_unsigned(tiff, big_tiff ? 8U : 4U, count, big_endian);
    if (!inline_payload.empty()) {
        tiff->insert(tiff->end(), inline_payload.begin(), inline_payload.end());
        tiff->resize(tiff->size() + inline_width - inline_payload.size(),
                     std::byte { 0x00 });
    } else {
        append_tiff_test_unsigned(tiff, inline_width, value_or_offset,
                                  big_endian);
    }
}

static std::vector<std::byte>
make_timestamp_exif_target(bool big_tiff, bool big_endian)
{
    static constexpr std::array<uint8_t, 10U> maker_note = {
        0x01U, 0x02U, 0x03U, 0x04U, 0x05U, 0x06U, 0x07U, 0x08U, 0x09U, 0x0AU,
    };
    const size_t count_width   = big_tiff ? 8U : 2U;
    const size_t entry_width   = big_tiff ? 20U : 12U;
    const size_t next_width    = big_tiff ? 8U : 4U;
    const uint64_t ifd0_offset = big_tiff ? 16U : 8U;
    const uint64_t ifd0_size   = count_width + 6U * entry_width + next_width;
    const uint64_t exif_ifd_offset = ifd0_offset + ifd0_size;
    const uint64_t exif_ifd_size = count_width + 27U * entry_width + next_width;
    const uint64_t interop_ifd_offset = exif_ifd_offset + exif_ifd_size;
    const uint64_t interop_ifd_size   = count_width + 2U * entry_width
                                      + next_width;
    const uint64_t gps_ifd_offset = interop_ifd_offset + interop_ifd_size;
    const uint64_t gps_ifd_size   = count_width + 2U * entry_width + next_width;
    const uint64_t storage_offset = gps_ifd_offset + gps_ifd_size;
    const uint64_t ifd0_time_offset     = storage_offset + 4U;
    const uint64_t original_time_offset = ifd0_time_offset + 20U;
    const uint64_t digitized_time_offset        = original_time_offset + 20U;
    const uint64_t offset_time_offset           = digitized_time_offset + 20U;
    const uint64_t offset_original_time_offset  = offset_time_offset + 7U;
    const uint64_t offset_digitized_time_offset = offset_original_time_offset
                                                  + 7U;
    const uint64_t maker_note_offset    = offset_digitized_time_offset + 7U;
    const uint64_t maker_note_end       = maker_note_offset + maker_note.size();
    const uint64_t exposure_bias_offset = (maker_note_end + 1U) & ~1ULL;
    const uint64_t lens_specification_offset = exposure_bias_offset + 8U;
    const uint64_t exposure_time_offset      = lens_specification_offset + 32U;
    const uint64_t f_number_offset           = exposure_time_offset + 8U;
    const uint64_t focal_length_offset       = f_number_offset + 8U;
    const uint64_t lens_make_offset          = focal_length_offset + 8U;
    const uint64_t lens_model_offset         = lens_make_offset + 15U;
    const uint64_t lens_serial_offset        = lens_model_offset + 15U;

    std::vector<std::byte> tiff;
    append_bytes(&tiff, big_endian ? "MM" : "II");
    if (big_tiff) {
        append_tiff_test_unsigned(&tiff, 2U, 43U, big_endian);
        append_tiff_test_unsigned(&tiff, 2U, 8U, big_endian);
        append_tiff_test_unsigned(&tiff, 2U, 0U, big_endian);
        append_tiff_test_unsigned(&tiff, 8U, ifd0_offset, big_endian);
    } else {
        append_tiff_test_unsigned(&tiff, 2U, 42U, big_endian);
        append_tiff_test_unsigned(&tiff, 4U, ifd0_offset, big_endian);
    }

    const std::vector<std::byte> root_width
        = make_tiff_test_unsigned(4U, 640U, big_endian);
    const std::vector<std::byte> strip_offset
        = make_tiff_test_unsigned(4U, storage_offset, big_endian);
    const std::vector<std::byte> strip_size
        = make_tiff_test_unsigned(4U, 4U, big_endian);
    const std::vector<std::byte> exif_pointer
        = make_tiff_test_unsigned(4U, exif_ifd_offset, big_endian);
    const std::vector<std::byte> gps_pointer
        = make_tiff_test_unsigned(big_tiff ? 8U : 4U, gps_ifd_offset,
                                  big_endian);
    append_tiff_test_unsigned(&tiff, count_width, 6U, big_endian);
    append_tiff_test_entry(&tiff, 0x0100U, 4U, 1U, 0U, root_width, big_tiff,
                           big_endian);
    append_tiff_test_entry(&tiff, 0x0111U, 4U, 1U, 0U, strip_offset, big_tiff,
                           big_endian);
    append_tiff_test_entry(&tiff, 0x0117U, 4U, 1U, 0U, strip_size, big_tiff,
                           big_endian);
    append_tiff_test_entry(&tiff, 0x0132U, 2U, 20U, ifd0_time_offset, {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x8769U, 4U, 1U, 0U, exif_pointer, big_tiff,
                           big_endian);
    append_tiff_test_entry(&tiff, 0x8825U, big_tiff ? 18U : 4U, 1U, 0U,
                           gps_pointer, big_tiff, big_endian);
    append_tiff_test_unsigned(&tiff, next_width, 0U, big_endian);

    const std::array<std::byte, 4U> exif_xmp = {
        std::byte { 'X' },
        std::byte { 'M' },
        std::byte { 'P' },
        std::byte { 0x00 },
    };
    const std::array<std::byte, 4U> interop_id = {
        std::byte { 'R' },
        std::byte { '9' },
        std::byte { '8' },
        std::byte { 0x00 },
    };
    const std::array<std::byte, 4U> interop_xmp = {
        std::byte { 'I' },
        std::byte { 'N' },
        std::byte { 'T' },
        std::byte { 0x00 },
    };
    const std::array<std::byte, 4U> gps_version = {
        std::byte { 0x02U },
        std::byte { 0x03U },
        std::byte { 0x00U },
        std::byte { 0x00U },
    };
    const std::array<std::byte, 2U> gps_latitude_ref = {
        std::byte { 'N' },
        std::byte { 0x00U },
    };
    const std::array<std::byte, 3U> subsec_original = {
        std::byte { '4' },
        std::byte { '5' },
        std::byte { 0x00 },
    };
    const std::array<std::byte, 3U> subsec_digitized = {
        std::byte { '2' },
        std::byte { '1' },
        std::byte { 0x00 },
    };
    const std::array<std::byte, 4U> subsec = {
        std::byte { '7' },
        std::byte { '8' },
        std::byte { '9' },
        std::byte { 0x00 },
    };
    const std::vector<std::byte> exposure = make_tiff_test_unsigned(2U, 7U,
                                                                    big_endian);
    std::vector<std::byte> exposure_bias;
    append_tiff_test_unsigned(&exposure_bias, 4U, UINT32_MAX, big_endian);
    append_tiff_test_unsigned(&exposure_bias, 4U, 3U, big_endian);
    std::vector<std::byte> exposure_time;
    append_tiff_test_unsigned(&exposure_time, 4U, 1U, big_endian);
    append_tiff_test_unsigned(&exposure_time, 4U, 125U, big_endian);
    std::vector<std::byte> f_number;
    append_tiff_test_unsigned(&f_number, 4U, 28U, big_endian);
    append_tiff_test_unsigned(&f_number, 4U, 10U, big_endian);
    std::vector<std::byte> focal_length;
    append_tiff_test_unsigned(&focal_length, 4U, 50U, big_endian);
    append_tiff_test_unsigned(&focal_length, 4U, 1U, big_endian);
    constexpr std::array<uint32_t, 8U> lens_specification_words = {
        50U, 3U, 200U, 3U, 14U, 5U, 0U, 0U,
    };
    std::vector<std::byte> lens_specification;
    for (uint32_t word : lens_specification_words) {
        append_tiff_test_unsigned(&lens_specification, 4U, word, big_endian);
    }
    std::vector<std::byte> lens_make;
    append_bytes(&lens_make, "Old Lens Maker");
    lens_make.push_back(std::byte { 0U });
    std::vector<std::byte> lens_model;
    append_bytes(&lens_model, "Old Lens Model");
    lens_model.push_back(std::byte { 0U });
    std::vector<std::byte> lens_serial;
    append_bytes(&lens_serial, "SN-OLD-0001");
    lens_serial.push_back(std::byte { 0U });
    const std::vector<std::byte> interop_pointer
        = make_tiff_test_unsigned(4U, interop_ifd_offset, big_endian);
    const std::vector<std::byte> sensitivity
        = make_tiff_test_unsigned(2U, 100U, big_endian);
    const std::vector<std::byte> sensitivity_type
        = make_tiff_test_unsigned(2U, 3U, big_endian);
    const std::vector<std::byte> standard_output_sensitivity
        = make_tiff_test_unsigned(4U, 100U, big_endian);
    const std::vector<std::byte> recommended_exposure_index
        = make_tiff_test_unsigned(4U, 200U, big_endian);
    const std::vector<std::byte> iso_speed
        = make_tiff_test_unsigned(4U, 400U, big_endian);
    const std::vector<std::byte> iso_latitude_yyy
        = make_tiff_test_unsigned(4U, 1U, big_endian);
    const std::vector<std::byte> iso_latitude_zzz
        = make_tiff_test_unsigned(4U, 1U, big_endian);
    append_tiff_test_unsigned(&tiff, count_width, 27U, big_endian);
    append_tiff_test_entry(&tiff, 700U, 7U, exif_xmp.size(), 0U, exif_xmp,
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x829AU, 5U, 1U, exposure_time_offset,
                           big_tiff ? std::span<const std::byte>(exposure_time)
                                    : std::span<const std::byte> {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x829DU, 5U, 1U, f_number_offset,
                           big_tiff ? std::span<const std::byte>(f_number)
                                    : std::span<const std::byte> {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x8827U, 3U, 1U, 0U, sensitivity, big_tiff,
                           big_endian);
    append_tiff_test_entry(&tiff, 0x8830U, 3U, 1U, 0U, sensitivity_type,
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x8831U, 4U, 1U, 0U,
                           standard_output_sensitivity, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x8832U, 4U, 1U, 0U,
                           recommended_exposure_index, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x8833U, 4U, 1U, 0U, iso_speed, big_tiff,
                           big_endian);
    append_tiff_test_entry(&tiff, 0x8834U, 4U, 1U, 0U, iso_latitude_yyy,
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x8835U, 4U, 1U, 0U, iso_latitude_zzz,
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9003U, 2U, 20U, original_time_offset, {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9004U, 2U, 20U, digitized_time_offset, {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9010U, 2U, 7U, offset_time_offset,
                           big_tiff ? std::as_bytes(
                                          std::span<const char>("+00:00", 7U))
                                    : std::span<const std::byte> {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9011U, 2U, 7U, offset_original_time_offset,
                           big_tiff ? std::as_bytes(
                                          std::span<const char>("+01:00", 7U))
                                    : std::span<const std::byte> {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9012U, 2U, 7U, offset_digitized_time_offset,
                           big_tiff ? std::as_bytes(
                                          std::span<const char>("+02:00", 7U))
                                    : std::span<const std::byte> {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9204U, 10U, 1U, exposure_bias_offset,
                           big_tiff ? std::span<const std::byte>(exposure_bias)
                                    : std::span<const std::byte> {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9209U, 3U, 1U, 0U, exposure, big_tiff,
                           big_endian);
    append_tiff_test_entry(&tiff, 0x920AU, 5U, 1U, focal_length_offset,
                           big_tiff ? std::span<const std::byte>(focal_length)
                                    : std::span<const std::byte> {},
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x927CU, 7U, maker_note.size(),
                           maker_note_offset, {}, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9290U, 2U, subsec.size(), 0U, subsec,
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9291U, 2U, subsec_original.size(), 0U,
                           subsec_original, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x9292U, 2U, subsec_digitized.size(), 0U,
                           subsec_digitized, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0xA005U, 4U, 1U, 0U, interop_pointer,
                           big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0xA432U, 5U, 4U, lens_specification_offset,
                           {}, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0xA433U, 2U, lens_make.size(),
                           lens_make_offset, {}, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0xA434U, 2U, lens_model.size(),
                           lens_model_offset, {}, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0xA435U, 2U, lens_serial.size(),
                           lens_serial_offset, {}, big_tiff, big_endian);
    append_tiff_test_unsigned(&tiff, next_width, 0U, big_endian);

    append_tiff_test_unsigned(&tiff, count_width, 2U, big_endian);
    append_tiff_test_entry(&tiff, 0x0001U, 2U, interop_id.size(), 0U,
                           interop_id, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 700U, 7U, interop_xmp.size(), 0U, interop_xmp,
                           big_tiff, big_endian);
    append_tiff_test_unsigned(&tiff, next_width, 0U, big_endian);

    append_tiff_test_unsigned(&tiff, count_width, 2U, big_endian);
    append_tiff_test_entry(&tiff, 0x0000U, 1U, gps_version.size(), 0U,
                           gps_version, big_tiff, big_endian);
    append_tiff_test_entry(&tiff, 0x0001U, 2U, gps_latitude_ref.size(), 0U,
                           gps_latitude_ref, big_tiff, big_endian);
    append_tiff_test_unsigned(&tiff, next_width, 0U, big_endian);

    tiff.push_back(std::byte { 0x11U });
    tiff.push_back(std::byte { 0x22U });
    tiff.push_back(std::byte { 0x33U });
    tiff.push_back(std::byte { 0x44U });
    append_bytes(&tiff, "2012:04:05 06:07:08");
    tiff.push_back(std::byte { 0x00 });
    append_bytes(&tiff, "2010:11:14 16:25:16");
    tiff.push_back(std::byte { 0x00 });
    append_bytes(&tiff, "2009:03:02 01:02:03");
    tiff.push_back(std::byte { 0x00 });
    append_bytes(&tiff, "+00:00");
    tiff.push_back(std::byte { 0x00 });
    append_bytes(&tiff, "+01:00");
    tiff.push_back(std::byte { 0x00 });
    append_bytes(&tiff, "+02:00");
    tiff.push_back(std::byte { 0x00 });
    for (size_t i = 0U; i < maker_note.size(); ++i) {
        tiff.push_back(static_cast<std::byte>(maker_note[i]));
    }
    if (tiff.size() < exposure_bias_offset) {
        tiff.push_back(std::byte { 0U });
    }
    tiff.insert(tiff.end(), exposure_bias.begin(), exposure_bias.end());
    tiff.insert(tiff.end(), lens_specification.begin(),
                lens_specification.end());
    tiff.insert(tiff.end(), exposure_time.begin(), exposure_time.end());
    tiff.insert(tiff.end(), f_number.begin(), f_number.end());
    tiff.insert(tiff.end(), focal_length.begin(), focal_length.end());
    tiff.insert(tiff.end(), lens_make.begin(), lens_make.end());
    tiff.insert(tiff.end(), lens_model.begin(), lens_model.end());
    tiff.insert(tiff.end(), lens_serial.begin(), lens_serial.end());
    return tiff;
}

static std::vector<std::byte>
make_minimal_tiff_timestamp_exif_target_little_endian()
{
    return make_timestamp_exif_target(false, false);
}

static std::vector<std::byte>
make_empty_source_exif_ifd_app1_payload()
{
    std::vector<std::byte> payload;
    append_bytes(&payload, "Exif");
    payload.push_back(std::byte { 0x00 });
    payload.push_back(std::byte { 0x00 });
    append_bytes(&payload, "II");
    append_u16le(&payload, 42U);
    append_u32le(&payload, 8U);
    append_u16le(&payload, 1U);
    append_u16le(&payload, 0x8769U);
    append_u16le(&payload, 4U);
    append_u32le(&payload, 1U);
    append_u32le(&payload, 26U);
    append_u32le(&payload, 0U);
    append_u16le(&payload, 0U);
    append_u32le(&payload, 0U);
    return payload;
}

static bool
build_minimal_transfer_target_for_format(openmeta::TransferTargetFormat format,
                                         std::vector<std::byte>* out)
{
    if (!out) {
        return false;
    }
    out->clear();

    if (format == openmeta::TransferTargetFormat::Jpeg) {
        *out = make_jpeg_with_segments({});
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Tiff
        || format == openmeta::TransferTargetFormat::Dng) {
        *out = make_minimal_tiff_little_endian();
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Png) {
        *out = build_minimal_png_file({});
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Webp) {
        *out = build_minimal_webp_file({}, 0U);
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Jp2) {
        *out = build_minimal_jp2_file({});
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Jxl) {
        *out = make_minimal_jxl_file();
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Heif) {
        *out = make_minimal_heif_file();
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Avif) {
        *out = make_minimal_avif_file();
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Cr3) {
        *out = make_minimal_cr3_file();
        return true;
    }

    return false;
}

static bool
build_minimal_bmff_transfer_target_with_unrelated_box_for_format(
    openmeta::TransferTargetFormat format, std::string_view token,
    std::vector<std::byte>* out)
{
    if (!out || token.empty()) {
        return false;
    }
    if (format != openmeta::TransferTargetFormat::Heif
        && format != openmeta::TransferTargetFormat::Avif
        && format != openmeta::TransferTargetFormat::Cr3) {
        return false;
    }
    if (!build_minimal_transfer_target_for_format(format, out)) {
        return false;
    }

    std::vector<std::byte> payload;
    append_bytes(&payload, token);
    append_bmff_box(out, openmeta::fourcc('f', 'r', 'e', 'e'),
                    std::span<const std::byte>(payload.data(), payload.size()));
    return true;
}

static bool
build_minimal_non_tiff_container_transfer_target_with_unrelated_payload_for_format(
    openmeta::TransferTargetFormat format, std::string_view token,
    std::vector<std::byte>* out)
{
    if (!out || token.empty()) {
        return false;
    }
    out->clear();

    std::vector<std::byte> payload;
    append_bytes(&payload, token);

    if (format == openmeta::TransferTargetFormat::Png) {
        std::vector<std::byte> text_chunk;
        append_bytes(&text_chunk, "Comment");
        text_chunk.push_back(std::byte { 0x00 });
        text_chunk.insert(text_chunk.end(), payload.begin(), payload.end());

        std::vector<std::byte> metadata;
        append_png_chunk(&metadata, openmeta::fourcc('t', 'E', 'X', 't'),
                         std::span<const std::byte>(text_chunk.data(),
                                                    text_chunk.size()));
        *out = build_minimal_png_file(
            std::span<const std::byte>(metadata.data(), metadata.size()));
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Webp) {
        std::vector<std::byte> metadata;
        append_webp_chunk(&metadata, openmeta::fourcc('f', 'r', 'e', 'e'),
                          std::span<const std::byte>(payload.data(),
                                                     payload.size()));
        *out = build_minimal_webp_file(
            std::span<const std::byte>(metadata.data(), metadata.size()), 0U);
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Jp2) {
        std::vector<std::byte> metadata;
        append_jp2_box(&metadata, openmeta::fourcc('f', 'r', 'e', 'e'),
                       std::span<const std::byte>(payload.data(),
                                                  payload.size()));
        *out = build_minimal_jp2_file(
            std::span<const std::byte>(metadata.data(), metadata.size()));
        return true;
    }
    if (format == openmeta::TransferTargetFormat::Jxl) {
        *out = make_minimal_jxl_file();
        append_bmff_box(out, openmeta::fourcc('f', 'r', 'e', 'e'),
                        std::span<const std::byte>(payload.data(),
                                                   payload.size()));
        return true;
    }

    return false;
}

