    EXPECT_TRUE(result.bundle.c2pa_rewrite.requires_manifest_builder);
    EXPECT_TRUE(result.bundle.c2pa_rewrite.requires_content_binding);
    EXPECT_TRUE(result.bundle.c2pa_rewrite.requires_certificate_chain);
