    EXPECT_FALSE(payload_contains_ascii(payload, "Legacy City"));
    EXPECT_FALSE(payload_contains_ascii(payload, "Legacy Wing"));
    EXPECT_FALSE(
        payload_contains_ascii(payload, ">XX</Iptc4xmpCore:CountryCode>"));
