TEST(MetadataTransferApi, TransferConceptDiagnosticsUseRawDataDescriptor)
{
    openmeta::MetaStore store;
    const openmeta::BlockId block = store.add_block(openmeta::BlockInfo {});
    ASSERT_NE(block, openmeta::kInvalidBlockId);

    openmeta::Entry black_level;
    black_level.key   = openmeta::make_exif_tag_key(store.arena(), "ifd0",
                                                    0xC61AU);
    black_level.value = openmeta::make_u32(512U);
    black_level.origin.block          = block;
    black_level.origin.order_in_block = 0U;
    ASSERT_NE(store.add_entry(black_level), openmeta::kInvalidEntryId);

    const std::array<uint32_t, 2> raw_curve_values = { 0U, 65535U };
    openmeta::Entry raw_curve;
    raw_curve.key = openmeta::make_exif_tag_key(store.arena(), "ifd0", 0xC618U);
    raw_curve.value = openmeta::make_u32_array(
        store.arena(), std::span<const uint32_t>(raw_curve_values.data(),
                                                 raw_curve_values.size()));
    raw_curve.origin.block          = block;
    raw_curve.origin.order_in_block = 1U;
    ASSERT_NE(store.add_entry(raw_curve), openmeta::kInvalidEntryId);
    store.finalize();

    openmeta::MetadataRawDataDescriptor stored_raw;
    stored_raw.encoding = openmeta::MetadataRawDataEncoding::LosslessCompressed;
    const openmeta::TransferConceptDiagnostics raw_compatible
        = openmeta::transfer_concept_diagnostics_from_store(
            store, openmeta::TransferSafetyMode::CompatibleFile, stored_raw);
    const openmeta::TransferConceptDiagnostic* raw_curve_diag
        = find_transfer_concept_diagnostic(
            raw_compatible, openmeta::MetadataConceptKind::RawProcessing,
            openmeta::MetadataConceptRole::RawValueCurve,
            openmeta::TransferConceptDiagnosticAction::Keep);
    ASSERT_NE(raw_curve_diag, nullptr);
    EXPECT_EQ(raw_curve_diag->raw_applicability,
              openmeta::MetadataRawApplicabilityState::AppliesToStoredRaw);
    EXPECT_FALSE(raw_curve_diag->raw_applicability_requires_storage_context);
    EXPECT_TRUE(raw_curve_diag->raw_applicability_can_affect_decode);

    openmeta::MetadataRawDataDescriptor secondary_plane = stored_raw;
    secondary_plane.requires_primary_raw_plane          = true;
    secondary_plane.has_plane_index                     = true;
    secondary_plane.plane_index                         = 1U;
    const openmeta::TransferConceptDiagnostics secondary_plane_compatible
        = openmeta::transfer_concept_diagnostics_from_store(
            store, openmeta::TransferSafetyMode::CompatibleFile,
            secondary_plane);
    const openmeta::TransferConceptDiagnostic* secondary_plane_curve_diag
        = find_transfer_concept_diagnostic(
            secondary_plane_compatible,
            openmeta::MetadataConceptKind::RawProcessing,
            openmeta::MetadataConceptRole::RawValueCurve,
            openmeta::TransferConceptDiagnosticAction::Drop);
    ASSERT_NE(secondary_plane_curve_diag, nullptr);
    EXPECT_EQ(
        secondary_plane_curve_diag->reason,
        openmeta::TransferConceptDiagnosticReason::RawApplicabilityNotApplicable);
    EXPECT_EQ(secondary_plane_curve_diag->raw_applicability,
              openmeta::MetadataRawApplicabilityState::NotApplicableToStoredRaw);
    EXPECT_FALSE(
        secondary_plane_curve_diag->raw_applicability_requires_storage_context);
    EXPECT_FALSE(
        secondary_plane_curve_diag->raw_applicability_can_affect_decode);

    openmeta::MetadataRawDataDescriptor rendered_data;
    rendered_data.encoding = openmeta::MetadataRawDataEncoding::Rendered;
    const openmeta::TransferConceptDiagnostics rendered_compatible
        = openmeta::transfer_concept_diagnostics_from_store(
            store, openmeta::TransferSafetyMode::CompatibleFile, rendered_data);
    const openmeta::TransferConceptDiagnostic* rendered_curve_diag
        = find_transfer_concept_diagnostic(
            rendered_compatible, openmeta::MetadataConceptKind::RawProcessing,
            openmeta::MetadataConceptRole::RawValueCurve,
            openmeta::TransferConceptDiagnosticAction::Drop);
    ASSERT_NE(rendered_curve_diag, nullptr);
    EXPECT_EQ(
        rendered_curve_diag->reason,
        openmeta::TransferConceptDiagnosticReason::RawApplicabilityNotApplicable);
    EXPECT_EQ(rendered_curve_diag->raw_applicability,
              openmeta::MetadataRawApplicabilityState::NotApplicableToStoredRaw);
    EXPECT_FALSE(
        rendered_curve_diag->raw_applicability_requires_storage_context);
    EXPECT_FALSE(rendered_curve_diag->raw_applicability_can_affect_decode);
    EXPECT_STREQ(openmeta::transfer_concept_diagnostic_message(
                     *rendered_curve_diag),
                 "RAW processing metadata does not apply to the supplied "
                 "storage descriptor and will be dropped");

    const openmeta::TransferConceptDiagnostic* rendered_black_diag
        = find_transfer_concept_diagnostic(
            rendered_compatible, openmeta::MetadataConceptKind::RawProcessing,
            openmeta::MetadataConceptRole::BlackLevel,
            openmeta::TransferConceptDiagnosticAction::Drop);
    ASSERT_NE(rendered_black_diag, nullptr);
    EXPECT_EQ(rendered_black_diag->raw_applicability,
              openmeta::MetadataRawApplicabilityState::NotApplicableToStoredRaw);
    EXPECT_EQ(
        rendered_black_diag->reason,
        openmeta::TransferConceptDiagnosticReason::RawApplicabilityNotApplicable);

    openmeta::MetadataRawDataDescriptor uncompressed_data;
    uncompressed_data.encoding = openmeta::MetadataRawDataEncoding::Uncompressed;
    uncompressed_data.requires_compressed_raw_encoding = true;
    const openmeta::TransferConceptDiagnostics uncompressed_compatible
        = openmeta::transfer_concept_diagnostics_from_store(
            store, openmeta::TransferSafetyMode::CompatibleFile,
            uncompressed_data);
    const openmeta::TransferConceptDiagnostic* uncompressed_curve_diag
        = find_transfer_concept_diagnostic(
            uncompressed_compatible,
            openmeta::MetadataConceptKind::RawProcessing,
            openmeta::MetadataConceptRole::RawValueCurve,
            openmeta::TransferConceptDiagnosticAction::Drop);
    ASSERT_NE(uncompressed_curve_diag, nullptr);
    EXPECT_EQ(
        uncompressed_curve_diag->reason,
        openmeta::TransferConceptDiagnosticReason::RawApplicabilityNotApplicable);
    EXPECT_EQ(uncompressed_curve_diag->raw_applicability,
              openmeta::MetadataRawApplicabilityState::NotApplicableToStoredRaw);

    const openmeta::TransferConceptDiagnostic* uncompressed_black_diag
        = find_transfer_concept_diagnostic(
            uncompressed_compatible,
            openmeta::MetadataConceptKind::RawProcessing,
            openmeta::MetadataConceptRole::BlackLevel,
            openmeta::TransferConceptDiagnosticAction::Keep);
    ASSERT_NE(uncompressed_black_diag, nullptr);
    EXPECT_EQ(uncompressed_black_diag->raw_applicability,
              openmeta::MetadataRawApplicabilityState::AppliesToStoredRaw);
}

TEST(MetadataTransferApi, TransferConceptDiagnosticsReportContainerGraphPolicy)
{
    openmeta::MetaStore store;
    const openmeta::EntryId component_content_bound
        = add_bmff_text(&store, "scene.component.metadata_policy",
                        "requires_target_rewrite");
    const openmeta::EntryId component_multi_image
        = add_bmff_text(&store, "scene.component.multi_image_policy",
                        "requires_target_rewrite");
    const openmeta::EntryId derived_construction
        = add_bmff_text(&store, "derived_image.construction", "overlay");
    const openmeta::EntryId tiled_configuration
        = add_bmff_text(&store, "tiled_image.configuration", "tiled");
    store.finalize();

    const openmeta::TransferConceptDiagnostics rendered
        = openmeta::transfer_concept_diagnostics_from_store(
            store, openmeta::TransferSafetyMode::RenderedImage);

    const openmeta::TransferConceptDiagnostic* content_bound_diag
        = find_transfer_concept_diagnostic(
            rendered, openmeta::MetadataConceptKind::ContainerGraph,
            openmeta::MetadataConceptRole::ContentBoundMetadata,
            openmeta::TransferConceptDiagnosticAction::Drop);
    ASSERT_NE(content_bound_diag, nullptr);
    EXPECT_EQ(content_bound_diag->reason,
              openmeta::TransferConceptDiagnosticReason::SourceBound);
    EXPECT_TRUE(content_bound_diag->source_bound);
    EXPECT_TRUE(contains_entry_id(content_bound_diag->source_entries,
                                  component_content_bound));
    EXPECT_EQ(openmeta::transfer_concept_diagnostic_token(*content_bound_diag),
              "warning:container_graph.content_bound_metadata:drop:"
              "source_bound");
    EXPECT_EQ(openmeta::transfer_concept_diagnostic_message_token(
                  *content_bound_diag),
              "drop.content_bound_metadata");
    EXPECT_STREQ(openmeta::transfer_concept_diagnostic_message(
                     *content_bound_diag),
                 "content-bound container metadata is bound to the source "
                 "container graph and will be dropped for this transfer mode");

    const openmeta::TransferConceptDiagnostic* multi_image_diag
        = find_transfer_concept_diagnostic(
            rendered, openmeta::MetadataConceptKind::ContainerGraph,
            openmeta::MetadataConceptRole::MultiImageScene,
            openmeta::TransferConceptDiagnosticAction::Drop);
    ASSERT_NE(multi_image_diag, nullptr);
    EXPECT_EQ(multi_image_diag->reason,
              openmeta::TransferConceptDiagnosticReason::SourceBound);
    EXPECT_TRUE(multi_image_diag->source_bound);
    EXPECT_TRUE(contains_entry_id(multi_image_diag->source_entries,
                                  component_multi_image));
    EXPECT_EQ(openmeta::transfer_concept_diagnostic_message_token(
                  *multi_image_diag),
              "drop.multi_image_scene");
    EXPECT_STREQ(openmeta::transfer_concept_diagnostic_message(
                     *multi_image_diag),
                 "multi-image container scene metadata is bound to the source "
                 "container graph and will be dropped for this transfer mode");

    const openmeta::TransferConceptDiagnostic* derived_diag
        = find_transfer_concept_diagnostic(
            rendered, openmeta::MetadataConceptKind::ContainerGraph,
            openmeta::MetadataConceptRole::DerivedImageConstruction,
            openmeta::TransferConceptDiagnosticAction::Drop);
    ASSERT_NE(derived_diag, nullptr);
    EXPECT_EQ(derived_diag->reason,
              openmeta::TransferConceptDiagnosticReason::SourceBound);
    EXPECT_TRUE(derived_diag->source_bound);
    EXPECT_TRUE(
        contains_entry_id(derived_diag->source_entries, derived_construction));
    EXPECT_EQ(openmeta::transfer_concept_diagnostic_message_token(*derived_diag),
              "drop.derived_image_construction");
    EXPECT_STREQ(openmeta::transfer_concept_diagnostic_message(*derived_diag),
                 "derived-image construction metadata is bound to the source "
                 "container graph and will be dropped for this transfer mode");

    const openmeta::TransferConceptDiagnostic* tiled_diag
        = find_transfer_concept_diagnostic(
            rendered, openmeta::MetadataConceptKind::ContainerGraph,
            openmeta::MetadataConceptRole::TiledImageConfiguration,
            openmeta::TransferConceptDiagnosticAction::Drop);
    ASSERT_NE(tiled_diag, nullptr);
    EXPECT_EQ(tiled_diag->reason,
              openmeta::TransferConceptDiagnosticReason::SourceBound);
    EXPECT_TRUE(tiled_diag->source_bound);
    EXPECT_TRUE(
        contains_entry_id(tiled_diag->source_entries, tiled_configuration));
    EXPECT_EQ(openmeta::transfer_concept_diagnostic_message_token(*tiled_diag),
              "drop.tiled_image_configuration");
    EXPECT_STREQ(openmeta::transfer_concept_diagnostic_message(*tiled_diag),
                 "tiled-image configuration metadata is bound to the source "
                 "container layout and will be dropped for this transfer "
                 "mode");

    const openmeta::TransferConceptDiagnostics compatible
        = openmeta::transfer_concept_diagnostics_from_store(
            store, openmeta::TransferSafetyMode::CompatibleFile);
    const openmeta::TransferConceptDiagnostic* compatible_content_bound
        = find_transfer_concept_diagnostic(
            compatible, openmeta::MetadataConceptKind::ContainerGraph,
            openmeta::MetadataConceptRole::ContentBoundMetadata,
            openmeta::TransferConceptDiagnosticAction::Keep);
    ASSERT_NE(compatible_content_bound, nullptr);
    EXPECT_EQ(compatible_content_bound->reason,
              openmeta::TransferConceptDiagnosticReason::SourceBound);
    const openmeta::TransferConceptDiagnostic* compatible_tiled
        = find_transfer_concept_diagnostic(
            compatible, openmeta::MetadataConceptKind::ContainerGraph,
            openmeta::MetadataConceptRole::TiledImageConfiguration,
            openmeta::TransferConceptDiagnosticAction::Keep);
    ASSERT_NE(compatible_tiled, nullptr);
    EXPECT_EQ(compatible_tiled->reason,
              openmeta::TransferConceptDiagnosticReason::SourceBound);
}

