TEST(MetadataTransferApi,
     CompatibleSafetyDecodedOnlyMakerNoteFieldsAreNotReconstructed)
{
    openmeta::MetaStore store;
    const openmeta::BlockId block = store.add_block(openmeta::BlockInfo {});
    ASSERT_NE(block, openmeta::kInvalidBlockId);

    openmeta::Entry make;
    make.key   = openmeta::make_exif_tag_key(store.arena(), "ifd0", 0x010FU);
    make.value = openmeta::make_text(store.arena(), "CameraVendor",
                                     openmeta::TextEncoding::Ascii);
    make.origin.block          = block;
    make.origin.order_in_block = 0U;
    ASSERT_NE(store.add_entry(make), openmeta::kInvalidEntryId);

    const std::vector<std::byte> decoded_makernote_bytes = ascii_z(
        "DECODED_ONLY_MAKERNOTE_FIELD");
    openmeta::Entry decoded_makernote;
    decoded_makernote.key   = openmeta::make_exif_tag_key(store.arena(),
                                                          "mk_sony_sr2private_0",
                                                          0x7200U);
    decoded_makernote.value = openmeta::make_bytes(
        store.arena(),
        std::span<const std::byte>(decoded_makernote_bytes.data(),
                                   decoded_makernote_bytes.size()));
    decoded_makernote.origin.block          = block;
    decoded_makernote.origin.order_in_block = 1U;
    ASSERT_NE(store.add_entry(decoded_makernote), openmeta::kInvalidEntryId);
    store.finalize();

    const openmeta::TransferMakerNoteAudit audit
        = openmeta::makernote_transfer_audit_from_store(store);
    EXPECT_EQ(audit.trust,
              openmeta::TransferMakerNoteTrust::DecodedOnlyNotSerializable);
    EXPECT_EQ(audit.raw_payload_count, 0U);
    EXPECT_EQ(audit.decoded_only_entry_count, 1U);
    EXPECT_FALSE(audit.opaque_payload_available);
    EXPECT_FALSE(audit.decoded_rewrite_available);
    EXPECT_FALSE(audit.internal_offset_relocation_available);
    EXPECT_FALSE(audit.vendor_checksum_recalculation_available);
    EXPECT_FALSE(audit.semantic_validation_available);
    EXPECT_FALSE(audit.raw_carrier_passthrough_available);

    openmeta::PrepareTransferRequest request;
    request.include_iptc_app13 = false;
    request.include_icc_app2   = false;
    request.include_xmp_app1   = false;
    request.profile.safety     = openmeta::TransferSafetyMode::CompatibleFile;

    openmeta::PreparedTransferBundle bundle;
    const openmeta::PrepareTransferResult result
        = openmeta::prepare_metadata_for_target(store, request, &bundle);

    ASSERT_EQ(result.status, openmeta::TransferStatus::Ok);
    EXPECT_EQ(result.code,
              openmeta::PrepareTransferCode::RequestedMetadataNotSerializable);
    EXPECT_EQ(result.errors, 0U);
    EXPECT_GE(result.warnings, 1U);
    EXPECT_TRUE(
        text_contains(result.message, "decoded-only maker note sub-ifd"));
    EXPECT_TRUE(text_contains(result.message,
                              "original raw MakerNote payload is required"));

    ASSERT_EQ(bundle.blocks.size(), 1U);
    ASSERT_EQ(bundle.blocks[0].kind, openmeta::TransferBlockKind::Exif);
    EXPECT_TRUE(
        prepared_exif_block_contains_ifd0_tag(bundle.blocks[0], 0x010FU));
    EXPECT_FALSE(payload_contains_ascii(
        std::span<const std::byte>(bundle.blocks[0].payload.data(),
                                   bundle.blocks[0].payload.size()),
        "DECODED_ONLY_MAKERNOTE_FIELD"));
    EXPECT_FALSE(
        prepared_exif_block_contains_exififd_tag(bundle.blocks[0], 0x927CU));

    const openmeta::PreparedTransferPolicyDecision* decision
        = find_policy_decision(bundle,
                               openmeta::TransferPolicySubject::MakerNote);
    ASSERT_NE(decision, nullptr);
    EXPECT_EQ(decision->requested, openmeta::TransferPolicyAction::Keep);
    EXPECT_EQ(decision->effective, openmeta::TransferPolicyAction::Drop);
    EXPECT_EQ(decision->reason,
              openmeta::TransferPolicyReason::TargetSerializationUnavailable);
    EXPECT_EQ(decision->matched_entries, 1U);
}

static bool
build_unmaterialized_ifd_pointer_source(openmeta::MetaStore* store)
{
    if (!store) {
        return false;
    }
    const openmeta::BlockId block = store->add_block(openmeta::BlockInfo {});
    if (block == openmeta::kInvalidBlockId) {
        return false;
    }

    openmeta::Entry make;
    make.key   = openmeta::make_exif_tag_key(store->arena(), "ifd0", 0x010FU);
    make.value = openmeta::make_text(store->arena(), "CameraVendor",
                                     openmeta::TextEncoding::Ascii);
    make.origin.block          = block;
    make.origin.order_in_block = 0U;
    if (store->add_entry(make) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry global_parameters;
    global_parameters.key = openmeta::make_exif_tag_key(store->arena(), "ifd0",
                                                        0x0190U);
    global_parameters.value                 = openmeta::make_u32(0xDEADBEEFU);
    global_parameters.origin.block          = block;
    global_parameters.origin.order_in_block = 1U;
    if (store->add_entry(global_parameters) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry extra_profiles;
    extra_profiles.key   = openmeta::make_exif_tag_key(store->arena(), "ifd0",
                                                       0xC6F5U);
    extra_profiles.value = openmeta::make_u32(0xCAFEBABEU);
    extra_profiles.origin.block          = block;
    extra_profiles.origin.order_in_block = 2U;
    if (store->add_entry(extra_profiles) == openmeta::kInvalidEntryId) {
        return false;
    }

    store->finalize();
    return true;
}

TEST(MetadataTransferApi,
     PrepareOmitsIfdPointersWhoseChildrenAreNotMaterialized)
{
    openmeta::MetaStore store;
    ASSERT_TRUE(build_unmaterialized_ifd_pointer_source(&store));

    openmeta::PrepareTransferRequest request;
    request.target_format      = openmeta::TransferTargetFormat::Dng;
    request.include_xmp_app1   = false;
    request.include_icc_app2   = false;
    request.include_iptc_app13 = false;
    request.profile.safety     = openmeta::TransferSafetyMode::CompatibleFile;

    openmeta::PreparedTransferBundle bundle;
    const openmeta::PrepareTransferResult result
        = openmeta::prepare_metadata_for_target(store, request, &bundle);

    ASSERT_EQ(result.status, openmeta::TransferStatus::Ok);
    EXPECT_EQ(result.errors, 0U);
    EXPECT_GE(result.warnings, 1U);
    EXPECT_TRUE(
        text_contains(result.message, "skipped 2 unsupported exif entries"));
    ASSERT_EQ(bundle.blocks.size(), 1U);
    ASSERT_EQ(bundle.blocks[0].kind, openmeta::TransferBlockKind::Exif);
    EXPECT_TRUE(
        prepared_exif_block_contains_ifd0_tag(bundle.blocks[0], 0x010FU));
    EXPECT_FALSE(
        prepared_exif_block_contains_ifd0_tag(bundle.blocks[0], 0x0190U));
    EXPECT_FALSE(
        prepared_exif_block_contains_ifd0_tag(bundle.blocks[0], 0xC6F5U));
}

TEST(MetadataTransferApi,
     RenderedSafetyReplacesImagePropertiesAndDropsSourceSpecificMetadata)
{
    openmeta::MetaStore store;
    ASSERT_TRUE(build_rendered_image_safety_source_store(&store));

    openmeta::PrepareTransferRequest request;
    request.include_iptc_app13   = false;
    request.xmp_include_existing = true;
    request.profile.safety       = openmeta::TransferSafetyMode::RenderedImage;
    request.target_image_spec.has_dimensions                 = true;
    request.target_image_spec.width                          = 320U;
    request.target_image_spec.height                         = 240U;
    request.target_image_spec.has_orientation                = true;
    request.target_image_spec.orientation                    = 1U;
    request.target_image_spec.has_samples_per_pixel          = true;
    request.target_image_spec.samples_per_pixel              = 1U;
    request.target_image_spec.bits_per_sample_count          = 1U;
    request.target_image_spec.bits_per_sample[0]             = 16U;
    request.target_image_spec.sample_format_count            = 1U;
    request.target_image_spec.sample_format[0]               = 1U;
    request.target_image_spec.has_photometric_interpretation = true;
    request.target_image_spec.photometric_interpretation     = 1U;
    request.target_image_spec.has_planar_configuration       = true;
    request.target_image_spec.planar_configuration           = 1U;

    openmeta::PreparedTransferBundle bundle;
    const openmeta::PrepareTransferResult result
        = openmeta::prepare_metadata_for_target(store, request, &bundle);
    ASSERT_EQ(result.status, openmeta::TransferStatus::Ok);
    EXPECT_EQ(result.errors, 0U);

    const openmeta::PreparedTransferBlock* exif_block = nullptr;
    for (size_t i = 0; i < bundle.blocks.size(); ++i) {
        if (bundle.blocks[i].kind == openmeta::TransferBlockKind::Exif) {
            exif_block = &bundle.blocks[i];
            break;
        }
    }

    ASSERT_NE(exif_block, nullptr);
    uint32_t value = 0U;
    uint32_t count = 0U;
    uint16_t type  = 0U;
    ASSERT_TRUE(prepared_exif_block_find_ifd0_tag(*exif_block, 0x0100U, &type,
                                                  &count, &value));
    EXPECT_EQ(value, 320U);
    ASSERT_TRUE(prepared_exif_block_find_ifd0_tag(*exif_block, 0x0101U, &type,
                                                  &count, &value));
    EXPECT_EQ(value, 240U);
    ASSERT_TRUE(prepared_exif_block_find_ifd0_tag(*exif_block, 0x0102U, &type,
                                                  &count, &value));
    EXPECT_EQ(type, 3U);
    EXPECT_EQ(count, 1U);
    EXPECT_EQ(value & 0xFFFFU, 16U);
    ASSERT_TRUE(prepared_exif_block_find_ifd0_tag(*exif_block, 0x0106U, &type,
                                                  &count, &value));
    EXPECT_EQ(value & 0xFFFFU, 1U);
    ASSERT_TRUE(prepared_exif_block_find_ifd0_tag(*exif_block, 0x0115U, &type,
                                                  &count, &value));
    EXPECT_EQ(value & 0xFFFFU, 1U);

    EXPECT_TRUE(prepared_exif_block_contains_ifd0_tag(*exif_block, 0x010FU));
    EXPECT_FALSE(prepared_exif_block_contains_ifd0_tag(*exif_block, 0xC621U));
    EXPECT_FALSE(prepared_exif_block_contains_ifd0_tag(*exif_block, 0xC71CU));
    EXPECT_FALSE(prepared_exif_block_contains_ifd0_tag(*exif_block, 0xC7A8U));
    EXPECT_TRUE(prepared_exif_block_contains_exififd_tag(*exif_block, 0x9003U));
    EXPECT_FALSE(
        prepared_exif_block_contains_exififd_tag(*exif_block, 0x927CU));
    EXPECT_FALSE(payload_contains_ascii(
        std::span<const std::byte>(exif_block->payload.data(),
                                   exif_block->payload.size()),
        "SOURCE_MAKERNOTE_DROP"));
    EXPECT_FALSE(payload_contains_ascii(
        std::span<const std::byte>(exif_block->payload.data(),
                                   exif_block->payload.size()),
        "SOURCE_VENDOR_PRIVATE_DROP"));
    EXPECT_FALSE(bundle_xmp_payload_contains_ascii(bundle, "Exposure2012"));
    EXPECT_FALSE(
        bundle_xmp_payload_contains_ascii(bundle, "Source Raw Profile"));

    const openmeta::PreparedTransferPolicyDecision* image_decision
        = find_policy_decision(bundle,
                               openmeta::TransferPolicySubject::ImageProperties);
    ASSERT_NE(image_decision, nullptr);
    EXPECT_EQ(image_decision->effective, openmeta::TransferPolicyAction::Drop);
    EXPECT_EQ(image_decision->matched_entries, 1U);

    const openmeta::PreparedTransferPolicyDecision* raw_decision
        = find_policy_decision(
            bundle, openmeta::TransferPolicySubject::RawColorCalibration);
    ASSERT_NE(raw_decision, nullptr);
    EXPECT_EQ(raw_decision->effective, openmeta::TransferPolicyAction::Drop);

    const openmeta::PreparedTransferPolicyDecision* crs_decision
        = find_policy_decision(
            bundle, openmeta::TransferPolicySubject::CameraRawSettings);
    ASSERT_NE(crs_decision, nullptr);
    EXPECT_EQ(crs_decision->effective, openmeta::TransferPolicyAction::Drop);
}

TEST(MetadataTransferApi, RenderedImageWritersOmitUnsafeSourceMetadata)
{
    openmeta::MetaStore store;
    const openmeta::BlockId block = store.add_block(openmeta::BlockInfo {});
    ASSERT_NE(block, openmeta::kInvalidBlockId);

    openmeta::Entry make;
    make.key   = openmeta::make_exif_tag_key(store.arena(), "ifd0", 0x010FU);
    make.value = openmeta::make_text(store.arena(), "CameraVendor",
                                     openmeta::TextEncoding::Ascii);
    make.origin.block          = block;
    make.origin.order_in_block = 0U;
    ASSERT_NE(store.add_entry(make), openmeta::kInvalidEntryId);

    openmeta::Entry datetime_original;
    datetime_original.key = openmeta::make_exif_tag_key(store.arena(),
                                                        "exififd", 0x9003U);
    datetime_original.value
        = openmeta::make_text(store.arena(), "2024:01:02 03:04:05",
                              openmeta::TextEncoding::Ascii);
    datetime_original.origin.block          = block;
    datetime_original.origin.order_in_block = 1U;
    ASSERT_NE(store.add_entry(datetime_original), openmeta::kInvalidEntryId);

    openmeta::Entry stale_width;
    stale_width.key   = openmeta::make_exif_tag_key(store.arena(), "ifd0",
                                                    0x0100U);
    stale_width.value = openmeta::make_u32(999U);
    stale_width.origin.block          = block;
    stale_width.origin.order_in_block = 2U;
    ASSERT_NE(store.add_entry(stale_width), openmeta::kInvalidEntryId);

    const std::array<openmeta::SRational, 9> color_matrix = {
        openmeta::SRational { 1, 1 }, openmeta::SRational { 0, 1 },
        openmeta::SRational { 0, 1 }, openmeta::SRational { 0, 1 },
        openmeta::SRational { 1, 1 }, openmeta::SRational { 0, 1 },
        openmeta::SRational { 0, 1 }, openmeta::SRational { 0, 1 },
        openmeta::SRational { 1, 1 },
    };
    openmeta::Entry raw_color;
    raw_color.key = openmeta::make_exif_tag_key(store.arena(), "ifd0", 0xC621U);
    raw_color.value = openmeta::make_srational_array(
        store.arena(),
        std::span<const openmeta::SRational>(color_matrix.data(),
                                             color_matrix.size()));
    raw_color.origin.block          = block;
    raw_color.origin.order_in_block = 3U;
    ASSERT_NE(store.add_entry(raw_color), openmeta::kInvalidEntryId);

    const std::vector<std::byte> vendor_private_bytes = ascii_z(
        "SOURCE_VENDOR_PRIVATE_DROP");
    openmeta::Entry vendor_private;
    vendor_private.key   = openmeta::make_exif_tag_key(store.arena(),
                                                       "mk_sony_sr2private_0",
                                                       0x7200U);
    vendor_private.value = openmeta::make_bytes(
        store.arena(), std::span<const std::byte>(vendor_private_bytes.data(),
                                                  vendor_private_bytes.size()));
    vendor_private.origin.block          = block;
    vendor_private.origin.order_in_block = 4U;
    ASSERT_NE(store.add_entry(vendor_private), openmeta::kInvalidEntryId);

    const std::vector<std::byte> makernote_bytes = ascii_z(
        "SOURCE_MAKERNOTE_DROP");
    openmeta::Entry makernote;
    makernote.key   = openmeta::make_exif_tag_key(store.arena(), "exififd",
                                                  0x927CU);
    makernote.value = openmeta::make_bytes(
        store.arena(), std::span<const std::byte>(makernote_bytes.data(),
                                                  makernote_bytes.size()));
    makernote.origin.block          = block;
    makernote.origin.order_in_block = 5U;
    ASSERT_NE(store.add_entry(makernote), openmeta::kInvalidEntryId);

    openmeta::Entry creator_tool;
    creator_tool.key = openmeta::make_xmp_property_key(
        store.arena(), "http://ns.adobe.com/xap/1.0/", "CreatorTool");
    creator_tool.value = openmeta::make_text(store.arena(), "OpenMeta Tool",
                                             openmeta::TextEncoding::Utf8);
    creator_tool.origin.block          = block;
    creator_tool.origin.order_in_block = 6U;
    ASSERT_NE(store.add_entry(creator_tool), openmeta::kInvalidEntryId);

    openmeta::Entry crs_exposure;
    crs_exposure.key = openmeta::make_xmp_property_key(
        store.arena(), "http://ns.adobe.com/camera-raw-settings/1.0/",
        "Exposure2012");
    crs_exposure.value        = openmeta::make_text(store.arena(), "+0.35",
                                                    openmeta::TextEncoding::Utf8);
    crs_exposure.origin.block = block;
    crs_exposure.origin.order_in_block = 7U;
    ASSERT_NE(store.add_entry(crs_exposure), openmeta::kInvalidEntryId);

    openmeta::Entry dng_profile_name;
    dng_profile_name.key = openmeta::make_xmp_property_key(
        store.arena(), "http://ns.adobe.com/dng/1.0/", "ProfileName");
    dng_profile_name.value                 = openmeta::make_text(store.arena(),
                                                                 "Source Raw Profile",
                                                                 openmeta::TextEncoding::Utf8);
    dng_profile_name.origin.block          = block;
    dng_profile_name.origin.order_in_block = 8U;
    ASSERT_NE(store.add_entry(dng_profile_name), openmeta::kInvalidEntryId);

    openmeta::Entry jumbf;
    jumbf.key          = openmeta::make_jumbf_cbor_key(store.arena(),
                                                       "box.0.1.cbor.manifest.label");
    jumbf.value        = openmeta::make_text(store.arena(), "source-manifest",
                                             openmeta::TextEncoding::Utf8);
    jumbf.origin.block = block;
    jumbf.origin.order_in_block = 9U;
    ASSERT_NE(store.add_entry(jumbf), openmeta::kInvalidEntryId);
    store.finalize();

    openmeta::PrepareTransferRequest jpeg_request;
    jpeg_request.include_iptc_app13   = false;
    jpeg_request.xmp_include_existing = true;
    jpeg_request.profile.safety = openmeta::TransferSafetyMode::RenderedImage;

    openmeta::PreparedTransferBundle jpeg_bundle;
    const openmeta::PrepareTransferResult jpeg_prepared
        = openmeta::prepare_metadata_for_target(store, jpeg_request,
                                                &jpeg_bundle);
    ASSERT_EQ(jpeg_prepared.status, openmeta::TransferStatus::Ok);

    std::vector<std::byte> old_xmp;
    append_bytes(&old_xmp, "http://ns.adobe.com/xap/1.0/");
    old_xmp.push_back(std::byte { 0x00 });
    append_bytes(&old_xmp,
                 "<x:xmpmeta><rdf:RDF><rdf:Description "
                 "crs:Exposure2012=\"+1.0\">"
                 "<dng:ProfileName>Old Source Raw Profile</dng:ProfileName>"
                 "</rdf:Description></rdf:RDF></x:xmpmeta>");
    const std::vector<std::byte> old_exif  = make_app1_exif_payload();
    const std::vector<std::byte> old_jumbf = make_app11_jumbf_payload(
        "old-source-jumbf");
    const TestJpegSegment segments[] = {
        TestJpegSegment { 0xE1U, std::span<const std::byte>(old_exif.data(),
                                                            old_exif.size()) },
        TestJpegSegment {
            0xE1U, std::span<const std::byte>(old_xmp.data(), old_xmp.size()) },
        TestJpegSegment { 0xEBU, std::span<const std::byte>(old_jumbf.data(),
                                                            old_jumbf.size()) },
    };
    const std::vector<std::byte> input_jpeg = make_jpeg_with_segments(
        std::span<const TestJpegSegment>(segments, std::size(segments)));
    const openmeta::JpegEditPlan jpeg_plan
        = openmeta::plan_prepared_bundle_jpeg_edit(
            std::span<const std::byte>(input_jpeg.data(), input_jpeg.size()),
            jpeg_bundle);
    ASSERT_EQ(jpeg_plan.status, openmeta::TransferStatus::Ok);
    EXPECT_EQ(jpeg_plan.selected_mode, openmeta::JpegEditMode::MetadataRewrite);
    EXPECT_GE(jpeg_plan.removed_existing_segments, 3U);

    std::vector<std::byte> output_jpeg;
    const openmeta::EmitTransferResult jpeg_applied
        = openmeta::apply_prepared_bundle_jpeg_edit(
            std::span<const std::byte>(input_jpeg.data(), input_jpeg.size()),
            jpeg_bundle, jpeg_plan, &output_jpeg);
    ASSERT_EQ(jpeg_applied.status, openmeta::TransferStatus::Ok);
    const std::span<const std::byte> output_jpeg_span(output_jpeg.data(),
                                                      output_jpeg.size());
    EXPECT_TRUE(payload_contains_ascii(output_jpeg_span, "CameraVendor"));
    EXPECT_TRUE(
        payload_contains_ascii(output_jpeg_span, "2024:01:02 03:04:05"));
    EXPECT_TRUE(payload_contains_ascii(output_jpeg_span, "OpenMeta Tool"));
    EXPECT_FALSE(
        payload_contains_ascii(output_jpeg_span, "2000:01:02 03:04:05"));
    EXPECT_FALSE(payload_contains_ascii(output_jpeg_span, "Exposure2012"));
    EXPECT_FALSE(
        payload_contains_ascii(output_jpeg_span, "Source Raw Profile"));
    EXPECT_FALSE(
        payload_contains_ascii(output_jpeg_span, "Old Source Raw Profile"));
    EXPECT_FALSE(payload_contains_ascii(output_jpeg_span, "old-source-jumbf"));
    EXPECT_FALSE(
        payload_contains_ascii(output_jpeg_span, "SOURCE_MAKERNOTE_DROP"));
    EXPECT_FALSE(
        payload_contains_ascii(output_jpeg_span, "SOURCE_VENDOR_PRIVATE_DROP"));

    openmeta::MetaStore decoded_jpeg;
    ASSERT_TRUE(
        decode_transfer_roundtrip_store(output_jpeg_span, &decoded_jpeg));
    EXPECT_TRUE(store_has_text_entry(decoded_jpeg,
                                     exif_key_view("ifd0", 0x010FU),
                                     "CameraVendor"));
    EXPECT_TRUE(store_has_text_entry(decoded_jpeg,
                                     exif_key_view("exififd", 0x9003U),
                                     "2024:01:02 03:04:05"));
    EXPECT_TRUE(
        store_has_text_entry(decoded_jpeg,
                             xmp_key_view("http://ns.adobe.com/xap/1.0/",
                                          "CreatorTool"),
                             "OpenMeta Tool"));
    EXPECT_EQ(decoded_jpeg.find_all(exif_key_view("ifd0", 0x0100U)).size(), 0U);
    EXPECT_EQ(decoded_jpeg.find_all(exif_key_view("ifd0", 0xC621U)).size(), 0U);
    EXPECT_EQ(decoded_jpeg.find_all(exif_key_view("exififd", 0x927CU)).size(),
              0U);
    EXPECT_EQ(decoded_jpeg
                  .find_all(xmp_key_view(
                      "http://ns.adobe.com/camera-raw-settings/1.0/",
                      "Exposure2012"))
                  .size(),
              0U);

    openmeta::PrepareTransferRequest tiff_request = jpeg_request;
    tiff_request.target_format = openmeta::TransferTargetFormat::Tiff;

    openmeta::PreparedTransferBundle tiff_bundle;
    const openmeta::PrepareTransferResult tiff_prepared
        = openmeta::prepare_metadata_for_target(store, tiff_request,
                                                &tiff_bundle);
    ASSERT_EQ(tiff_prepared.status, openmeta::TransferStatus::Ok);

    const std::vector<std::byte> input_tiff = make_minimal_tiff_little_endian();
    const openmeta::TiffEditPlan tiff_plan
        = openmeta::plan_prepared_bundle_tiff_edit(
            std::span<const std::byte>(input_tiff.data(), input_tiff.size()),
            tiff_bundle);
    ASSERT_EQ(tiff_plan.status, openmeta::TransferStatus::Ok);

    std::vector<std::byte> output_tiff;
    const openmeta::EmitTransferResult tiff_applied
        = openmeta::apply_prepared_bundle_tiff_edit(
            std::span<const std::byte>(input_tiff.data(), input_tiff.size()),
            tiff_bundle, tiff_plan, &output_tiff);
    ASSERT_EQ(tiff_applied.status, openmeta::TransferStatus::Ok);
    const std::span<const std::byte> output_tiff_span(output_tiff.data(),
                                                      output_tiff.size());
    EXPECT_TRUE(payload_contains_ascii(output_tiff_span, "CameraVendor"));
    EXPECT_TRUE(
        payload_contains_ascii(output_tiff_span, "2024:01:02 03:04:05"));
    EXPECT_TRUE(payload_contains_ascii(output_tiff_span, "OpenMeta Tool"));
    EXPECT_FALSE(payload_contains_ascii(output_tiff_span, "Exposure2012"));
    EXPECT_FALSE(
        payload_contains_ascii(output_tiff_span, "Source Raw Profile"));
    EXPECT_FALSE(
        payload_contains_ascii(output_tiff_span, "SOURCE_MAKERNOTE_DROP"));
    EXPECT_FALSE(
        payload_contains_ascii(output_tiff_span, "SOURCE_VENDOR_PRIVATE_DROP"));

    openmeta::MetaStore decoded_tiff;
    ASSERT_TRUE(
        decode_transfer_roundtrip_store(output_tiff_span, &decoded_tiff));
    EXPECT_TRUE(store_has_text_entry(decoded_tiff,
                                     exif_key_view("ifd0", 0x010FU),
                                     "CameraVendor"));
    EXPECT_TRUE(store_has_text_entry(decoded_tiff,
                                     exif_key_view("exififd", 0x9003U),
                                     "2024:01:02 03:04:05"));
    EXPECT_TRUE(
        store_has_text_entry(decoded_tiff,
                             xmp_key_view("http://ns.adobe.com/xap/1.0/",
                                          "CreatorTool"),
                             "OpenMeta Tool"));
    EXPECT_EQ(decoded_tiff.find_all(exif_key_view("ifd0", 0x0100U)).size(), 0U);
    EXPECT_EQ(decoded_tiff.find_all(exif_key_view("ifd0", 0xC621U)).size(), 0U);
    EXPECT_EQ(decoded_tiff.find_all(exif_key_view("exififd", 0x927CU)).size(),
              0U);
    EXPECT_EQ(decoded_tiff
                  .find_all(xmp_key_view(
                      "http://ns.adobe.com/camera-raw-settings/1.0/",
                      "Exposure2012"))
                  .size(),
              0U);
}

struct RenderedImageContainerWriterCase final {
    const char* label;
    openmeta::TransferTargetFormat format;
};

TEST(MetadataTransferApi, RenderedImageContainerWritersOmitUnsafeSourceMetadata)
{
    openmeta::MetaStore store;
    ASSERT_TRUE(build_rendered_image_safety_source_store(&store));

    static constexpr RenderedImageContainerWriterCase kCases[] = {
        { "tiff", openmeta::TransferTargetFormat::Tiff },
        { "dng", openmeta::TransferTargetFormat::Dng },
        { "png", openmeta::TransferTargetFormat::Png },
        { "webp", openmeta::TransferTargetFormat::Webp },
        { "jp2", openmeta::TransferTargetFormat::Jp2 },
        { "jxl", openmeta::TransferTargetFormat::Jxl },
        { "heif", openmeta::TransferTargetFormat::Heif },
        { "avif", openmeta::TransferTargetFormat::Avif },
        { "cr3", openmeta::TransferTargetFormat::Cr3 },
    };

    for (size_t i = 0; i < std::size(kCases); ++i) {
        SCOPED_TRACE(kCases[i].label);

        openmeta::PrepareTransferRequest request;
        request.target_format        = kCases[i].format;
        request.include_iptc_app13   = false;
        request.xmp_include_existing = true;
        request.profile.safety = openmeta::TransferSafetyMode::RenderedImage;

        openmeta::PreparedTransferBundle bundle;
        const openmeta::PrepareTransferResult prepared
            = openmeta::prepare_metadata_for_target(store, request, &bundle);
        ASSERT_EQ(prepared.status, openmeta::TransferStatus::Ok);
        ASSERT_EQ(prepared.errors, 0U);
        EXPECT_EQ(bundle.profile.safety,
                  openmeta::TransferSafetyMode::RenderedImage);

        std::vector<std::byte> input;
        ASSERT_TRUE(build_test_target_with_existing_creator_tool_xmp(
            kCases[i].format, "Old Source Raw Profile", &input));
        ASSERT_FALSE(input.empty());
        const std::span<const std::byte> input_span(input.data(), input.size());
        ASSERT_TRUE(
            payload_contains_ascii(input_span, "Old Source Raw Profile"));

        openmeta::ExecutePreparedTransferOptions options;
        options.edit_requested = true;
        options.edit_apply     = true;
        const openmeta::ExecutePreparedTransferResult applied
            = openmeta::execute_prepared_transfer(&bundle, input_span, options);
        ASSERT_EQ(applied.edit_plan_status, openmeta::TransferStatus::Ok);
        ASSERT_EQ(applied.edit_apply.status, openmeta::TransferStatus::Ok);
        ASSERT_FALSE(applied.edited_output.empty());

        const std::span<const std::byte> edited(applied.edited_output.data(),
                                                applied.edited_output.size());
        EXPECT_FALSE(payload_contains_ascii(edited, "Old Source Raw Profile"));
        expect_rendered_image_safety_output(edited);

        openmeta::PreparedTransferPackageBatch batch;
        const openmeta::EmitTransferResult batch_result
            = openmeta::build_executed_transfer_package_batch(input_span,
                                                              bundle, applied,
                                                              &batch);
        ASSERT_EQ(batch_result.status, openmeta::TransferStatus::Ok);
        ASSERT_EQ(batch.output_size,
                  static_cast<uint64_t>(applied.edited_output.size()));

        openmeta::EmitTransferResult write_result;
        const std::vector<std::byte> batch_bytes
            = materialize_transfer_package_batch(batch, &write_result);
        ASSERT_EQ(write_result.status, openmeta::TransferStatus::Ok);
        ASSERT_EQ(batch_bytes.size(), applied.edited_output.size());
        EXPECT_EQ(std::memcmp(batch_bytes.data(), applied.edited_output.data(),
                              applied.edited_output.size()),
                  0);
    }
}

TEST(MetadataTransferApi, PrepareRejectsInvalidTargetImageSpec)
{
    openmeta::MetaStore store;
    store.finalize();

    openmeta::PrepareTransferRequest request;
    request.include_icc_app2                 = false;
    request.include_iptc_app13               = false;
    request.target_image_spec.has_dimensions = true;
    request.target_image_spec.width          = 0U;
    request.target_image_spec.height         = 480U;

    openmeta::PreparedTransferBundle bundle;
    const openmeta::PrepareTransferResult result
        = openmeta::prepare_metadata_for_target(store, request, &bundle);

    EXPECT_EQ(result.status, openmeta::TransferStatus::InvalidArgument);
    EXPECT_EQ(result.code,
              openmeta::PrepareTransferCode::RequestedMetadataNotSerializable);
    EXPECT_EQ(result.errors, 1U);
    EXPECT_TRUE(text_contains(result.message, "dimensions"));
}

static std::vector<std::byte>
make_nikon_type3_transfer_makernote()
{
    std::vector<std::byte> note;
    append_bytes(&note, "Nikon");
    note.push_back(std::byte { 0 });
    note.push_back(std::byte { 2 });
    note.push_back(std::byte { 0 });
    note.push_back(std::byte { 0 });
    note.push_back(std::byte { 0 });

    append_bytes(&note, "II");
    append_u16le(&note, 42U);
    append_u32le(&note, 8U);
    append_u16le(&note, 2U);

    append_u16le(&note, 0x0001U);
    append_u16le(&note, 4U);
    append_u32le(&note, 1U);
    append_u32le(&note, 0x01020304U);

    append_u16le(&note, 0x001FU);
    append_u16le(&note, 7U);
    append_u32le(&note, 8U);
    append_u32le(&note, 38U);
    append_u32le(&note, 0U);

    append_bytes(&note, "0101");
    note.push_back(std::byte { 1 });
    note.push_back(std::byte { 0 });
    note.push_back(std::byte { 2 });
    note.push_back(std::byte { 0 });
    return note;
}

static std::vector<std::byte>
make_nikon_type1_transfer_makernote()
{
    std::vector<std::byte> note;
    append_bytes(&note, "Nikon");
    note.push_back(std::byte { 0 });
    note.push_back(std::byte { 1 });
    note.push_back(std::byte { 0 });
    append_u16le(&note, 1U);
    append_u16le(&note, 0x0001U);
    append_u16le(&note, 4U);
    append_u32le(&note, 1U);
    append_u32le(&note, 0x01020304U);
    append_u32le(&note, 0U);
    return note;
}

static std::vector<std::byte>
make_canon_source_dependent_transfer_makernote()
{
    std::vector<std::byte> note;
    append_u16le(&note, 1U);
    append_u16le(&note, 0x0001U);
    append_u16le(&note, 3U);
    append_u32le(&note, 1U);
    append_u16le(&note, 7U);
    append_u16le(&note, 0U);
    append_u32le(&note, 0U);
    return note;
}

static bool
build_makernote_transfer_store(std::span<const std::byte> note,
                               std::string_view camera_make,
                               openmeta::MetaStore* out) noexcept
{
    if (!out) {
        return false;
    }
    *out                          = openmeta::MetaStore {};
    const openmeta::BlockId block = out->add_block(openmeta::BlockInfo {});
    if (block == openmeta::kInvalidBlockId) {
        return false;
    }

    openmeta::Entry make;
    make.key   = openmeta::make_exif_tag_key(out->arena(), "ifd0", 0x010FU);
    make.value = openmeta::make_text(out->arena(), camera_make,
                                     openmeta::TextEncoding::Ascii);
    make.origin.block          = block;
    make.origin.order_in_block = 0U;
    if (out->add_entry(make) == openmeta::kInvalidEntryId) {
        return false;
    }

    openmeta::Entry maker;
    maker.key   = openmeta::make_exif_tag_key(out->arena(), "exififd", 0x927CU);
    maker.value = openmeta::make_bytes(out->arena(), note);
    maker.origin.block          = block;
    maker.origin.order_in_block = 1U;
    if (out->add_entry(maker) == openmeta::kInvalidEntryId) {
        return false;
    }
    out->finalize();
    return true;
}

static bool
add_test_makernote_audit_payload(
    openmeta::MetaStore* store, openmeta::BlockId block, std::string_view ifd,
    uint16_t tag, std::span<const std::byte> payload, uint32_t order,
    openmeta::EntryFlags flags = openmeta::EntryFlags::None) noexcept
{
    if (!store || block == openmeta::kInvalidBlockId) {
        return false;
    }
    openmeta::Entry entry;
    entry.key          = openmeta::make_exif_tag_key(store->arena(), ifd, tag);
    entry.value        = openmeta::make_bytes(store->arena(), payload);
    entry.flags        = flags;
    entry.origin.block = block;
    entry.origin.order_in_block = order;
    return store->add_entry(entry) != openmeta::kInvalidEntryId;
}

static bool
add_test_makernote_audit_make(openmeta::MetaStore* store,
                              openmeta::BlockId block, std::string_view ifd,
                              std::string_view camera_make, uint32_t order,
                              openmeta::EntryFlags flags
                              = openmeta::EntryFlags::None) noexcept
{
    if (!store || block == openmeta::kInvalidBlockId) {
        return false;
    }
    openmeta::Entry entry;
    entry.key   = openmeta::make_exif_tag_key(store->arena(), ifd, 0x010FU);
    entry.value = openmeta::make_text(store->arena(), camera_make,
                                      openmeta::TextEncoding::Ascii);
    entry.flags = flags;
    entry.origin.block          = block;
    entry.origin.order_in_block = order;
    return store->add_entry(entry) != openmeta::kInvalidEntryId;
}

TEST(MetadataTransferApi, AuditsNikonMakerNoteOffsetLayoutsConservatively)
{
    const std::vector<std::byte> type3 = make_nikon_type3_transfer_makernote();
    openmeta::MetaStore type3_store;
    ASSERT_TRUE(build_makernote_transfer_store(type3, "Nikon", &type3_store));

    const openmeta::TransferMakerNoteLayoutAudit type3_audit
        = openmeta::makernote_layout_transfer_audit_from_store(type3_store);
    EXPECT_EQ(
        type3_audit.trust,
        openmeta::TransferMakerNoteLayoutTrust::EmbeddedTiffStructureVerified);
    EXPECT_EQ(type3_audit.vendor, openmeta::TransferMakerNoteVendor::Nikon);
    EXPECT_EQ(type3_audit.layout,
              openmeta::TransferMakerNoteLayout::NikonType3EmbeddedTiff);
    EXPECT_EQ(type3_audit.raw_payload_count, 1U);
    EXPECT_EQ(type3_audit.recognized_payload_count, 1U);
    EXPECT_EQ(type3_audit.structurally_valid_payload_count, 1U);
    EXPECT_TRUE(type3_audit.offset_basis_known);
    EXPECT_TRUE(type3_audit.embedded_tiff_validation_available);
    EXPECT_TRUE(type3_audit.embedded_tiff_validation_passed);
    EXPECT_TRUE(type3_audit.embedded_tiff_offsets_self_contained);
    EXPECT_FALSE(type3_audit.outer_tiff_offset_relocation_required);
    EXPECT_FALSE(type3_audit.vendor_private_offsets_verified);
    EXPECT_FALSE(type3_audit.vendor_checksum_validation_available);
    EXPECT_FALSE(type3_audit.semantic_roundtrip_validation_available);

    const openmeta::TransferMakerNoteAudit generic_audit
        = openmeta::makernote_transfer_audit_from_store(type3_store);
    EXPECT_EQ(generic_audit.trust,
              openmeta::TransferMakerNoteTrust::OpaquePreservationUnverified);
    EXPECT_EQ(generic_audit.raw_payload_count, 1U);
    EXPECT_EQ(generic_audit.decoded_only_entry_count, 0U);

    const std::vector<std::byte> type1 = make_nikon_type1_transfer_makernote();
    openmeta::MetaStore type1_store;
    ASSERT_TRUE(build_makernote_transfer_store(type1, "Nikon", &type1_store));
    const openmeta::TransferMakerNoteLayoutAudit type1_audit
        = openmeta::makernote_layout_transfer_audit_from_store(type1_store);
    EXPECT_EQ(type1_audit.raw_payload_count, 1U);
    EXPECT_EQ(type1_audit.trust,
              openmeta::TransferMakerNoteLayoutTrust::OuterTiffOffsetsUnsafe);
    EXPECT_EQ(type1_audit.vendor, openmeta::TransferMakerNoteVendor::Nikon);
    EXPECT_EQ(type1_audit.layout,
              openmeta::TransferMakerNoteLayout::NikonType1OuterTiff);
    EXPECT_TRUE(type1_audit.offset_basis_known);
    EXPECT_TRUE(type1_audit.outer_tiff_offset_relocation_required);
    EXPECT_FALSE(type1_audit.embedded_tiff_validation_available);
    EXPECT_FALSE(type1_audit.embedded_tiff_offsets_self_contained);
    const openmeta::TransferMakerNoteAudit type1_generic
        = openmeta::makernote_transfer_audit_from_store(type1_store);
    EXPECT_EQ(type1_generic.raw_payload_count, 1U);
    EXPECT_EQ(type1_generic.decoded_only_entry_count, 0U);

    std::vector<std::byte> truncated_type3 = type3;
    ASSERT_FALSE(truncated_type3.empty());
    truncated_type3.pop_back();
    openmeta::MetaStore truncated_store;
    ASSERT_TRUE(build_makernote_transfer_store(truncated_type3, "Nikon",
                                               &truncated_store));
    const openmeta::TransferMakerNoteLayoutAudit truncated_audit
        = openmeta::makernote_layout_transfer_audit_from_store(truncated_store);
    EXPECT_EQ(
        truncated_audit.trust,
        openmeta::TransferMakerNoteLayoutTrust::EmbeddedTiffStructureUnverified);
    EXPECT_EQ(truncated_audit.layout,
              openmeta::TransferMakerNoteLayout::NikonType3EmbeddedTiff);
    EXPECT_TRUE(truncated_audit.embedded_tiff_validation_available);
    EXPECT_FALSE(truncated_audit.embedded_tiff_validation_passed);
    EXPECT_FALSE(truncated_audit.embedded_tiff_offsets_self_contained);
}

TEST(MetadataTransferApi, MakerNoteAuditsRequireExpectedIfdKeys)
{
    const std::vector<std::byte> type3 = make_nikon_type3_transfer_makernote();
    openmeta::MetaStore wrong_makernote_ifd;
    const openmeta::BlockId wrong_makernote_block
        = wrong_makernote_ifd.add_block(openmeta::BlockInfo {});
    ASSERT_NE(wrong_makernote_block, openmeta::kInvalidBlockId);
    ASSERT_TRUE(add_test_makernote_audit_make(&wrong_makernote_ifd,
                                              wrong_makernote_block, "ifd0",
                                              "Nikon", 0U));
    ASSERT_TRUE(add_test_makernote_audit_payload(
        &wrong_makernote_ifd, wrong_makernote_block, "ifd0", 0x927CU,
        std::span<const std::byte>(type3.data(), type3.size()), 1U));
    wrong_makernote_ifd.finalize();

    const openmeta::TransferMakerNoteAudit absent_generic
        = openmeta::makernote_transfer_audit_from_store(wrong_makernote_ifd);
    EXPECT_EQ(absent_generic.trust,
              openmeta::TransferMakerNoteTrust::NotPresent);
    EXPECT_EQ(absent_generic.raw_payload_count, 0U);
    EXPECT_FALSE(absent_generic.opaque_payload_available);

    const openmeta::TransferMakerNoteLayoutAudit absent_layout
        = openmeta::makernote_layout_transfer_audit_from_store(
            wrong_makernote_ifd);
    EXPECT_EQ(absent_layout.trust,
              openmeta::TransferMakerNoteLayoutTrust::NotPresent);
    EXPECT_EQ(absent_layout.raw_payload_count, 0U);
    EXPECT_EQ(absent_layout.vendor, openmeta::TransferMakerNoteVendor::Unknown);

    const std::vector<std::byte> canon_note
        = make_canon_source_dependent_transfer_makernote();

    openmeta::MetaStore wrong_make_ifd;
    const openmeta::BlockId wrong_make_block = wrong_make_ifd.add_block(
        openmeta::BlockInfo {});
    ASSERT_NE(wrong_make_block, openmeta::kInvalidBlockId);
    ASSERT_TRUE(add_test_makernote_audit_make(&wrong_make_ifd, wrong_make_block,
                                              "exififd", "Canon Inc.", 0U));
    ASSERT_TRUE(add_test_makernote_audit_payload(
        &wrong_make_ifd, wrong_make_block, "exififd", 0x927CU,
        std::span<const std::byte>(canon_note.data(), canon_note.size()), 1U));
    wrong_make_ifd.finalize();

    const openmeta::TransferMakerNoteAudit generic
        = openmeta::makernote_transfer_audit_from_store(wrong_make_ifd);
    EXPECT_EQ(generic.trust,
              openmeta::TransferMakerNoteTrust::OpaquePreservationUnverified);
    EXPECT_EQ(generic.raw_payload_count, 1U);

    const openmeta::TransferMakerNoteLayoutAudit layout
        = openmeta::makernote_layout_transfer_audit_from_store(wrong_make_ifd);
    EXPECT_EQ(layout.trust,
              openmeta::TransferMakerNoteLayoutTrust::UnrecognizedOrMixed);
    EXPECT_EQ(layout.raw_payload_count, 1U);
    EXPECT_EQ(layout.recognized_payload_count, 0U);
    EXPECT_EQ(layout.vendor, openmeta::TransferMakerNoteVendor::Unknown);
    EXPECT_FALSE(layout.source_offset_context_required);
}

TEST(MetadataTransferApi,
     MakerNoteAuditsIgnoreDeletedEvidenceAndCountSameNumberedDecodedTags)
{
    const std::vector<std::byte> type3 = make_nikon_type3_transfer_makernote();
    const std::vector<std::byte> canon_note
        = make_canon_source_dependent_transfer_makernote();

    openmeta::MetaStore deleted_makernote_store;
    const openmeta::BlockId deleted_makernote_block
        = deleted_makernote_store.add_block(openmeta::BlockInfo {});
    ASSERT_NE(deleted_makernote_block, openmeta::kInvalidBlockId);
    ASSERT_TRUE(add_test_makernote_audit_make(&deleted_makernote_store,
                                              deleted_makernote_block, "ifd0",
                                              "Nikon", 0U));
    ASSERT_TRUE(add_test_makernote_audit_payload(
        &deleted_makernote_store, deleted_makernote_block, "exififd", 0x927CU,
        std::span<const std::byte>(type3.data(), type3.size()), 1U,
        openmeta::EntryFlags::Deleted));
    deleted_makernote_store.finalize();

    const openmeta::TransferMakerNoteAudit deleted_raw
        = openmeta::makernote_transfer_audit_from_store(
            deleted_makernote_store);
    EXPECT_EQ(deleted_raw.trust, openmeta::TransferMakerNoteTrust::NotPresent);
    EXPECT_EQ(deleted_raw.raw_payload_count, 0U);
    const openmeta::TransferMakerNoteLayoutAudit deleted_layout
        = openmeta::makernote_layout_transfer_audit_from_store(
            deleted_makernote_store);
    EXPECT_EQ(deleted_layout.trust,
              openmeta::TransferMakerNoteLayoutTrust::NotPresent);
    EXPECT_EQ(deleted_layout.raw_payload_count, 0U);

    openmeta::MetaStore deleted_make_store;
    const openmeta::BlockId deleted_make_block = deleted_make_store.add_block(
        openmeta::BlockInfo {});
    ASSERT_NE(deleted_make_block, openmeta::kInvalidBlockId);
    ASSERT_TRUE(add_test_makernote_audit_make(&deleted_make_store,
                                              deleted_make_block, "ifd0",
                                              "Canon Inc.", 0U,
                                              openmeta::EntryFlags::Deleted));
    ASSERT_TRUE(add_test_makernote_audit_payload(
        &deleted_make_store, deleted_make_block, "exififd", 0x927CU,
        std::span<const std::byte>(canon_note.data(), canon_note.size()), 1U));
    deleted_make_store.finalize();

    const openmeta::TransferMakerNoteAudit deleted_make_generic
        = openmeta::makernote_transfer_audit_from_store(deleted_make_store);
    EXPECT_EQ(deleted_make_generic.trust,
              openmeta::TransferMakerNoteTrust::OpaquePreservationUnverified);
    EXPECT_EQ(deleted_make_generic.raw_payload_count, 1U);
    const openmeta::TransferMakerNoteLayoutAudit deleted_make_layout
        = openmeta::makernote_layout_transfer_audit_from_store(
            deleted_make_store);
    EXPECT_EQ(deleted_make_layout.trust,
              openmeta::TransferMakerNoteLayoutTrust::UnrecognizedOrMixed);
    EXPECT_EQ(deleted_make_layout.raw_payload_count, 1U);
    EXPECT_EQ(deleted_make_layout.recognized_payload_count, 0U);
    EXPECT_EQ(deleted_make_layout.vendor,
              openmeta::TransferMakerNoteVendor::Unknown);

    openmeta::MetaStore decoded_only_store;
    const openmeta::BlockId decoded_only_block = decoded_only_store.add_block(
        openmeta::BlockInfo {});
    ASSERT_NE(decoded_only_block, openmeta::kInvalidBlockId);
    ASSERT_TRUE(add_test_makernote_audit_payload(
        &decoded_only_store, decoded_only_block, "mk_canon0", 0x927CU,
        std::span<const std::byte>(canon_note.data(), canon_note.size()), 0U));
    decoded_only_store.finalize();

    const openmeta::TransferMakerNoteAudit decoded_only
        = openmeta::makernote_transfer_audit_from_store(decoded_only_store);
    EXPECT_EQ(decoded_only.trust,
              openmeta::TransferMakerNoteTrust::DecodedOnlyNotSerializable);
    EXPECT_EQ(decoded_only.raw_payload_count, 0U);
    EXPECT_EQ(decoded_only.decoded_only_entry_count, 1U);
    EXPECT_FALSE(decoded_only.opaque_payload_available);
    const openmeta::TransferMakerNoteLayoutAudit decoded_only_layout
        = openmeta::makernote_layout_transfer_audit_from_store(
            decoded_only_store);
    EXPECT_EQ(decoded_only_layout.trust,
              openmeta::TransferMakerNoteLayoutTrust::NotPresent);
    EXPECT_EQ(decoded_only_layout.raw_payload_count, 0U);
}

