    ASSERT_TRUE(decode_transfer_roundtrip_store(
        std::span<const std::byte>(result.execute.edited_output.data(),
                                   result.execute.edited_output.size()),
        &decoded));
    const std::array<uint8_t, 4> dng_version = { 1U, 6U, 0U, 0U };
