    options.execute.edit_apply                 = true;
    options.xmp_writeback_mode = openmeta::XmpWritebackMode::SidecarOnly;
    options.xmp_destination_embedded_mode
        = openmeta::XmpDestinationEmbeddedMode::StripExisting;

