    ASSERT_NE(block, openmeta::kInvalidBlockId);

    openmeta::Entry exif;
    exif.key = openmeta::make_exif_tag_key(source.arena(), "exififd", 0x9003U);
    exif.value = openmeta::make_text(source.arena(), "2025:06:07 08:09:10",
                                     openmeta::TextEncoding::Ascii);
